local config = {
  ui_story_5066_50660101_1_dialog_content = "Stairs, closets, floors...",
  ui_story_5066_50660101_2_dialog_content = "Phew... They're finally all clean.",
  ui_story_5066_50660101_3_dialog_content = "That means I should be done with today's cleaning... Right?",
  ui_story_5066_50660101_4_dialog_content = "Connolly! Where did you go? Is the floor all cleaned?",
  ui_story_5066_50660101_5_dialog_content = "Ah! It's my aunt!",
  ui_story_5066_50660101_6_dialog_content = "I-I'm in the basement! I just finished down here!",
  ui_story_5066_50660101_7_dialog_content = "Really? Because I've just spotted some stains in the corridor again!",
  ui_story_5066_50660101_8_dialog_content = "We have important guests coming over these days, and the whole family is busy. Don't be a drag!",
  ui_story_5066_50660101_9_dialog_content = "Okay... I'll be right there!",
  ui_story_5066_50660101_10_dialog_content = "This should be the place...",
  ui_story_5066_50660101_11_dialog_content = "Ah! This whole area is covered in sand from people's shoes...",
  ui_story_5066_50660101_12_dialog_content = "I need to clean this up right away and head straight for the attic...",
  ui_story_5066_50660101_13_dialog_content = "Otherwise... My aunt will dislike me even more if she sees this.",
  ui_story_5066_50660101_14_dialog_content = "Hey, Connolly!",
  ui_story_5066_50660101_15_dialog_content = "Eek—Is that you, cousin?",
  ui_story_5066_50660101_16_dialog_content = "B-But I thought you were promoted to a high position back in the Shallows...",
  ui_story_5066_50660101_17_dialog_content = "Haha, it's surprising you still remember all this. I'm indeed a valued member of the Merman Court now.",
  ui_story_5066_50660101_18_dialog_content = "Are you also cleaning the living room today? Quite a homemaker, little Connolly!",
  ui_story_5066_50660101_19_dialog_content = "I'll be finished soon enough... I won't waste any more of everyone's time!",
  ui_story_5066_50660101_20_dialog_content = "Aren't you going to attend the family banquet?",
  ui_story_5066_50660101_21_dialog_content = "I-I could never possibly attend...",
  ui_story_5066_50660101_22_dialog_content = "During banquets... My aunt either locks me in the attic or forces me to leave the house...",
  ui_story_5066_50660101_23_dialog_content = "She doesn't want to scare our guests, since I look so strange...",
  ui_story_5066_50660101_24_dialog_content = "Such a shame. Your appearance is indeed quite peculiar for a resident of this underwater town.",
  ui_story_5066_50660101_25_dialog_content = "Yet, in my eyes, this peculiarity is a form of aesthetics.",
  ui_story_5066_50660101_26_dialog_content = "I can introduce you to a better job, where you won't be alone anymore.",
  ui_story_5066_50660101_27_dialog_content = "F-Forgive me, but I should be going now! My aunt still has plenty of things for me to do!",
  ui_story_5066_50660101_28_dialog_content = "Hey, hold on!",
  ui_story_5066_50660101_29_dialog_content = "... Unappreciative!",
  ui_story_5066_50660101_30_dialog_content = "Ah, thank goodness I managed to escape...",
  ui_story_5066_50660101_31_dialog_content = "He seems really interested in me, but his sleazy attitude really makes me feel uncomfortable...",
  ui_story_5066_50660101_32_dialog_content = "Even if I could leave... It wouldn't be with him...",
  ui_story_5066_50660101_33_dialog_content = "I know I'd feel lonely if I left on my own... But I really don't mind being alone.",
  ui_story_5066_50660101_34_dialog_content = "Honestly, being in a place with no other people suits me perfectly.",
  ui_story_5066_50660101_35_dialog_content = "<color=#e8d9bb>Connolly believes that if nobody notices her, then nobody can hate her, shun her, or point fingers at her.</color>",
  ui_story_5066_50660101_36_dialog_content = "Who's that? Her appearance is really strange—it doesn't resemble a fish at all. Is she from the town?",
  ui_story_5066_50660101_37_dialog_content = "Her name's Connolly, I heard. And she's adopted.",
  ui_story_5066_50660101_38_dialog_content = "No idea what kind of fish her parents were to have a kid this weird.",
  ui_story_5066_50660101_39_dialog_content = "I'm the only one who looks different in this house...",
  ui_story_5066_50660101_40_dialog_content = "Mama and Papa are gone now... Only my aunt was willing to take me in...",
  ui_story_5066_50660101_41_dialog_content = "But no matter how hard I try to be a part of this family... There's just no place for me here.",
  ui_story_5066_50660101_42_dialog_content = "Still, I'm not completely unhappy...",
  ui_story_5066_50660101_43_dialog_content = "And that's because... I still have my music! I still have the instrument and sheet music my mama left me...",
  ui_story_5066_50660101_44_dialog_content = "<color=#e8d9bb>Whenever Connolly feels lonely, she plays those familiar melodies.</color>",
  ui_story_5066_50660101_45_dialog_content = "<color=#e8d9bb>A joyful march in A Major, a lyrical ballad in B Minor, and a somber sonata in C Major. These songs are not just her friends, but her salvation.</color>",
  ui_story_5066_50660101_46_dialog_content = "Now which song should I play today...?",
  ui_story_5066_50660101_47_dialog_content = "Huh...? This score...",
  ui_story_5066_50660101_48_dialog_content = "Wh-Wh-What's this scary piece of music still doing here?!",
  ui_story_5066_50660101_49_dialog_content = "The last time I played it, something extremely terrible happened!",
  ui_story_5066_50660101_50_dialog_content = "It even summoned a tentacled monster, one that called itself...",
  ui_story_5066_50660101_51_dialog_content = "I am the <color=#FFB400>Aqua Lord</color>...",
  ui_story_5066_50660101_52_dialog_content = "The sealed... ancient... Aqua Lord!",
  ui_story_5066_50660101_53_dialog_content = "The ordinary daughter of the water holding the sacred relic, can you comprehend my words?",
  ui_story_5066_50660101_54_dialog_content = "...?",
  ui_story_5066_50660101_55_dialog_content = "Aaaaaaaah! I-It's a monster!",
  ui_story_5066_50660101_56_dialog_content = "Please don't eat me!!!",
  ui_story_5066_50660101_57_dialog_content = "... I never consume mortal beings!",
  ui_story_5066_50660101_58_dialog_content = "I am here because your clarinet is no ordinary thing...",
  ui_story_5066_50660101_59_dialog_content = "Your music led me here.",
  ui_story_5066_50660101_60_dialog_content = "I wish to form a pact with you.",
  ui_story_5066_50660101_61_dialog_content = "A... pact?",
  ui_story_5066_50660101_62_dialog_content = "Yes, the mighty Aqua Pact! With the pact, you can be the queen and rule the entire undersea world!",
  ui_story_5066_50660101_63_dialog_content = "The queen... of the undersea world...",
  ui_story_5066_50660101_64_dialog_content = "Then, all you have to do is play the sacred relic that symbolizes our pact... this very clarinet!",
  ui_story_5066_50660101_65_dialog_content = "My power will manifest, aiding you in conquering all the seas!",
  ui_story_5066_50660101_66_dialog_content = "You won't have to fear anything in the world anymore!",
  ui_story_5066_50660101_67_dialog_content = "Now, tell me, what's your answer?",
  ui_story_5066_50660101_68_dialog_content = "... May I please refuse?",
  ui_story_5066_50660101_69_dialog_content = "?",
  ui_story_5066_50660101_70_dialog_content = "Ah! Uh, y-you know... About becoming queen and stuff...",
  ui_story_5066_50660101_71_dialog_content = "I don't think I can do something that sounds so difficult or noticeable...",
  ui_story_5066_50660101_72_dialog_content = "M-My biggest wish is for people to stop noticing me...",
  ui_story_5066_50660101_73_dialog_content = "I don't want any trouble. I just want to listen to my music...",
  ui_story_5066_50660101_74_dialog_content = "<size=33>If I had just one or two friends, or maybe even three to listen to music with me... That would be enough...</size>",
  ui_story_5066_50660101_75_dialog_content = "...",
  ui_story_5066_50660101_76_dialog_content = "I see. You're not ready to bear the responsibility of the underwater realm.",
  ui_story_5066_50660101_77_dialog_content = "But this sheet music is evidence of our potential pact.",
  ui_story_5066_50660101_78_dialog_content = "To call upon me, play it with your clarinet.",
  ui_story_5066_50660101_79_dialog_content = "Just play it... play it... play it...",
  ui_story_5066_50660101_80_dialog_content = "I thought this was just mama's precious instrument that she left to me...",
  ui_story_5066_50660101_81_dialog_content = "Why can it summon such a mysterious creature...?",
  ui_story_5066_50660101_82_dialog_content = "It's not going to stay with me forever... Is it?",
  ui_story_5066_50660101_83_dialog_content = "Play it...",
  ui_story_5066_50660101_84_dialog_content = "The pact...",
  ui_story_5066_50660101_85_dialog_content = "To call upon me...",
  ui_story_5066_50660101_86_dialog_content = "Ahhhhh... Just thinking about it makes me hear its voice again!",
  ui_story_5066_50660101_87_dialog_content = "I just need to... focus on something else...",
  ui_story_5066_50660101_88_dialog_content = "<color=#e8d9bb>Knock, knock, knock—</color>",
  ui_story_5066_50660101_89_dialog_content = "Huh? Who could be looking for me in the attic at this hour...?",
  ui_story_5066_50660101_90_dialog_content = "Connolly! We're running low on kitchen ingredients again! Hurry and go buy some!",
  ui_story_5066_50660101_91_dialog_content = "Oh... Okay! I'll head out right now!",
  ui_story_5066_50660201_1_dialog_content = "Phew... This should keep my aunt from getting too angry.",
  ui_story_5066_50660201_2_dialog_content = "Still, what's happening today...?",
  ui_story_5066_50660201_3_dialog_content = "Is it time yet? Why haven't they come?",
  ui_story_5066_50660201_4_dialog_content = "Excuse me, pardon me...",
  ui_story_5066_50660201_5_dialog_content = "Boo-hoo... Why are the streets so packed today?",
  ui_story_5066_50660201_6_dialog_content = "It looks like everyone came out to see something... Is today some kind of special holiday...?",
  ui_story_5066_50660201_7_dialog_content = "What did you say?",
  ui_story_5066_50660201_8_dialog_content = "You mean you don't know? Today is the <color=#FFB400>prince's</color> day out today! Everyone's out on the streets, trying to catch a glimpse of the prince!",
  ui_story_5066_50660201_9_dialog_content = "Huh, I'd like to see the face of the guy who taxes us all the time!",
  ui_story_5066_50660201_10_dialog_content = "... I didn't expect to run into this today. Crowds like this scare me the most.",
  ui_story_5066_50660201_11_dialog_content = "I need to hurry back as soon as I finish buying supplies...",
  ui_story_5066_50660201_12_dialog_content = "It's the prince! The prince is here!",
  ui_story_5066_50660201_13_dialog_content = "Ha!",
  ui_story_5066_50660201_14_dialog_content = "Ugh, this is just boring, so, so boring!",
  ui_story_5066_50660201_15_dialog_content = "What a lousy town. I might as well stay indoors and never come out. Why did my dad give this rundown dump to me?",
  ui_story_5066_50660201_16_dialog_content = "Your Highness, please calm down.",
  ui_story_5066_50660201_17_dialog_content = "After all, this is also your territory, and everyone's eager to meet you.",
  ui_story_5066_50660201_18_dialog_content = "Then they should cough up more taxes... Hold on a sec!",
  ui_story_5066_50660201_19_dialog_content = "Check out this girl! She's really one of a kind...",
  ui_story_5066_50660201_20_dialog_content = "Seriously, does fish with such a peculiar look really exist?",
  ui_story_5066_50660201_21_dialog_content = "She might look a little weird, but as a collectible, she's probably super valuable.",
  ui_story_5066_50660201_22_dialog_content = "<size=33>Tsk, what's Connolly doing here... Isn't she supposed to be in the attic?</size>",
  ui_story_5066_50660201_23_dialog_content = "<size=33>But I didn't expect the prince to be interested in her; this might be a rare opportunity...</size>",
  ui_story_5066_50660201_24_dialog_content = "Your Highness, it's a bit embarrassing to admit, but this girl is actually my sister.",
  ui_story_5066_50660201_25_dialog_content = "She's practically a jinx at home. But when it comes to unique looks, no one can outmatch her.",
  ui_story_5066_50660201_26_dialog_content = "If you're interested, I can sell... offer her to you right away.",
  ui_story_5066_50660201_27_dialog_content = "Oh, that's kinda convenient. How thoughtful of you.",
  ui_story_5066_50660201_28_dialog_content = "But first, I'm gonna get a closer look to figure out what's the deal with her.",
  ui_story_5066_50660201_29_dialog_content = "It's about time I got some fun out of visiting this crappy town. Gotta make the most of it.",
  ui_story_5066_50660201_30_dialog_content = "Right this way, Your Highness. If you need any assistance, feel free to give your orders.",
  ui_story_5066_50660201_31_dialog_content = "The prince's crew is on the move!",
  ui_story_5066_50660201_32_dialog_content = "Where's he going? Come on, let's tag along and see what's up!",
  ui_story_5066_50660201_33_dialog_content = "Ah—The crowd is moving again!",
  ui_story_5066_50660201_34_dialog_content = "W-W-Wait! I'm getting pushed out...",
  ui_story_5066_50660201_35_dialog_content = "Oof!",
  ui_story_5066_50660201_36_dialog_content = "...",
  ui_story_5066_50660201_37_dialog_content = "Who's this girl? She dares to fall in the prince's way.",
  ui_story_5066_50660201_38_dialog_content = "Wow, she looks so weird; doesn't look like a fish at all!",
  ui_story_5066_50660201_39_dialog_content = "Ouch! Oh no... Please tell me my clothes didn't get dirty! I don't have enough clothes to begin with...",
  ui_story_5066_50660201_40_dialog_content = "Why does it feel like everyone is staring at me...?",
  ui_story_5066_50660201_41_dialog_content = "Hey, you down there! Stop staring around—I mean you!",
  ui_story_5066_50660201_42_dialog_content = "Eek!",
  ui_story_5066_50660201_43_dialog_content = "Your rather ugly appearance has caught my eye.",
  ui_story_5066_50660201_44_dialog_content = "Here's my invitation to you—to become a treasured piece in my collection!",
  ui_story_5066_50660201_45_dialog_content = "Trust me, life with me in the shallow waters is way better than being stuck in this crappy town.",
  ui_story_5066_50660201_46_dialog_content = "You know what I mean, right?",
  ui_story_5066_50660201_47_dialog_content = "Um... M-May I please refuse?",
  ui_story_5066_50660201_48_dialog_content = "Connolly, don't let my goodwill go to waste!",
  ui_story_5066_50660201_49_dialog_content = "I've really talked you up before the prince so you could have this opportunity!",
  ui_story_5066_50660201_50_dialog_content = "Is this the new job you were telling me about...?",
  ui_story_5066_50660201_51_dialog_content = "You wanted to... <size=45>sell me to the prince?!</size>",
  ui_story_5066_50660201_52_dialog_content = "Don't make it sound so bad. It's not selling; it's making you an honored royal companion...",
  ui_story_5066_50660201_53_dialog_content = "As your cousin, I've found the best path for you.",
  ui_story_5066_50660201_54_dialog_content = "Otherwise, you'll be forever stuck at home doing servant's work. Don't you find it lonely?",
  ui_story_5066_50660201_55_dialog_content = "Lonely...? I told you before, I don't get lonely. All I need is my music and my clarinet!",
  ui_story_5066_50660201_56_dialog_content = "Clarinet? Is that the weird instrument in your hand?",
  ui_story_5066_50660201_57_dialog_content = "Wow, it seems like some ancient artifact... quite unusual.",
  ui_story_5066_50660201_58_dialog_content = "Present it to me for a closer look.",
  ui_story_5066_50660201_59_dialog_content = "Ah! I... I can't let you!",
  ui_story_5066_50660201_60_dialog_content = "Nobody gets to say no to me under the sea! Hand it over!",
  ui_story_5066_50660201_61_dialog_content = "But... But my mother left it to me...",
  ui_story_5066_50660201_62_dialog_content = "Mother? Speaking of which, with your unique appearance, I'm quite curious about what your mother looked like.",
  ui_story_5066_50660201_63_dialog_content = "If possible, it'd be awesome if both of you could be my collectibles together.",
  ui_story_5066_50660201_64_dialog_content = "...?",
  ui_story_5066_50660201_65_dialog_content = "Please don't look at me, Your Highness. She's adopted; her mother isn't mine...",
  ui_story_5066_50660201_66_dialog_content = "No...",
  ui_story_5066_50660201_67_dialog_content = "What?!",
  ui_story_5066_50660201_68_dialog_content = "I won't let you insult Mama like that!",
  ui_story_5066_50660201_69_dialog_content = "Ridiculous!",
  ui_story_5066_50660201_70_dialog_content = "Under the seas here, nobody's had the audacity to talk to me like that.",
  ui_story_5066_50660201_71_dialog_content = "Since you're not willing to hand it over... don't blame me for being rude!",
  ui_story_5066_50660201_72_dialog_content = "<color=#e8d9bb>The prince leaps towards Connolly.</color>",
  ui_story_5066_50660201_73_dialog_content = "No... Get away from me...!",
  ui_story_5066_50660201_74_dialog_content = "<color=#e8d9bb><size=45>Smack—</size></color>",
  ui_story_5066_50660201_75_dialog_content = "<size=45>Ouch!!!</size>",
  ui_story_5066_50660201_76_dialog_content = "...?!",
  ui_story_5066_50660201_77_dialog_content = "...!!!",
  ui_story_5066_50660201_78_dialog_content = "How... how dare you attack me with a weapon?!",
  ui_story_5066_50660201_79_dialog_content = "Ah... I-I'm so sorry, I didn't mean to do that...",
  ui_story_5066_50660201_80_dialog_content = "B-But even so... <size=30>This was your own fault...</size>",
  ui_story_5066_50660201_81_dialog_content = "What did you say?... Guards! Where are the guards?!",
  ui_story_5066_50660201_82_dialog_content = "Grab that bold, malformed girl for me!",
  ui_story_5066_50660201_83_dialog_content = "Yes!!!",
  ui_story_5066_50660201_84_dialog_content = "Aaah... Connolly, you troublemaker! We're screwed...",
  ui_story_5066_50660201_85_dialog_content = "Oh no... I-I think I'm in really big trouble now...",
  ui_story_5066_50660201_86_dialog_content = "I'm done for if they catch me, no doubt about it... I have to run away! There's no other choice for me!",
  ui_story_5066_50660201_87_dialog_content = "Pardon me... Please let me through!",
  ui_story_5066_50660201_88_dialog_content = "<color=#e8d9bb>She wants to escape the crowd, to hide in a place where no one can find her.</color>",
  ui_story_5066_50660201_89_dialog_content = "<color=#e8d9bb>But is that even possible in a bustling, undersea street like this...?</color>",
  ui_story_5066_50660302_1_dialog_content = "Ugh... Standing guard is the most boring job in the world!",
  ui_story_5066_50660302_2_dialog_content = "Are there really no bad guys around? I wouldn't mind a nice scuffle right now.",
  ui_story_5066_50660302_3_dialog_content = "Compared to fighting... I'd much rather prefer if we could just be together in peace...",
  ui_story_5066_50660302_4_dialog_content = "Yes, I know. I wasn't being serious, I was just blowing off steam.",
  ui_story_5066_50660302_5_dialog_content = "Okay...",
  ui_story_5066_50660302_6_dialog_content = "Though I wouldn't mind if Connolly came to chat for a bit either!",
  ui_story_5066_50660302_7_dialog_content = "We haven't seen her in a while, huh?",
  ui_story_5066_50660302_8_dialog_content = "I hear... Her family is expecting some sort of important guest... She's probably been busy taking care of the house.",
  ui_story_5066_50660302_9_dialog_content = "Taking care of the house?",
  ui_story_5066_50660302_10_dialog_content = "Ugh, if she's been cooped up at home all this time, I'm sure her annoying aunt has been making life miserable for her.",
  ui_story_5066_50660302_11_dialog_content = "If I ever get the chance, I really want to smack her once or twice for Connolly!",
  ui_story_5066_50660302_12_dialog_content = "I... wouldn't stop you from doing that.",
  ui_story_5066_50660302_13_dialog_content = "Connolly has been helping us with our errands all this time, but we haven't had a chance to repay her... It's really starting to weigh on me...",
  ui_story_5066_50660302_14_dialog_content = "I know, right?",
  ui_story_5066_50660302_15_dialog_content = "She won't accept any money for it either. She even says she's thankful to us...",
  ui_story_5066_50660302_16_dialog_content = "Oh... I really don't need any money for running errands for you...",
  ui_story_5066_50660302_17_dialog_content = "I'm... I'm just happy to get out of the house every once in a while...",
  ui_story_5066_50660302_18_dialog_content = "After all... My aunt would scold me most of the time whenever I was at home...",
  ui_story_5066_50660302_19_dialog_content = "So, please... please call on me if you have any errands you need me to run!",
  ui_story_5066_50660302_20_dialog_content = "She really is a good girl, huh.",
  ui_story_5066_50660302_21_dialog_content = "She's nothing like that greedy, cunning witch we used to work for!",
  ui_story_5066_50660302_22_dialog_content = "<size=45>Ohhhhhh!</size>",
  ui_story_5066_50660302_23_dialog_content = "What's with all the noise? Is something happening over there?",
  ui_story_5066_50660302_24_dialog_content = "Yes... And it seems pretty lively too.",
  ui_story_5066_50660302_25_dialog_content = "I really wanna go take a look! How much longer do we have to stand around and keep guard?!",
  ui_story_5066_50660302_26_dialog_content = "I know how you feel... But it's still really early in our shift...",
  ui_story_5066_50660302_27_dialog_content = "Anyway, this kind of ruckus is pretty common.",
  ui_story_5066_50660302_28_dialog_content = "With such an arrogant king and a pompous prince, the denizens of the sea have been having a rough time.",
  ui_story_5066_50660302_29_dialog_content = "Could it be that the stupid prince was attacked by angry residents? Now, that would be interesting.",
  ui_story_5066_50660302_30_dialog_content = "If something like that actually happened right in front of me...",
  ui_story_5066_50660302_31_dialog_content = "I'd just pretend I didn't see anything...",
  ui_story_5066_50660302_32_dialog_content = "Over here!",
  ui_story_5066_50660302_33_dialog_content = "Hey, you two!",
  ui_story_5066_50660302_34_dialog_content = "The prince's guards?",
  ui_story_5066_50660302_35_dialog_content = "Don't tell me I was right...",
  ui_story_5066_50660302_36_dialog_content = "Have you seen a peculiar-looking girl running this way, someone carrying a clarinet?",
  ui_story_5066_50660302_37_dialog_content = "...",
  ui_story_5066_50660302_38_dialog_content = "(It's Connolly...)",
  ui_story_5066_50660302_39_dialog_content = "(What does the prince want with her?)",
  ui_story_5066_50660302_40_dialog_content = "(Whatever he's planning, we can't let him have his way.)",
  ui_story_5066_50660302_41_dialog_content = "Never mind, I don't expect you've seen her. You two are members of the search team now! Start searching from here!",
  ui_story_5066_50660302_42_dialog_content = "Uh... May we ask what happened just now...?",
  ui_story_5066_50660302_43_dialog_content = "What happened? Heh, that peculiar-looking girl actually dared to strike the prince!",
  ui_story_5066_50660302_44_dialog_content = "This is unprecedented!",
  ui_story_5066_50660302_45_dialog_content = "She'll regret it once I catch her!",
  ui_story_5066_50660302_46_dialog_content = "<size=33>Good, Connolly! Nice one!</size>",
  ui_story_5066_50660302_47_dialog_content = "What did you just say?",
  ui_story_5066_50660302_48_dialog_content = "Oh nothing, just that we'll do our jobs as best as we can.",
  ui_story_5066_50660302_49_dialog_content = "Well then, get your butts moving!",
  ui_story_5066_50660302_50_dialog_content = "Yes, sir!",
  ui_story_5066_50660302_51_dialog_content = "...",
  ui_story_5066_50660302_52_dialog_content = "Oh, no, Connolly's in serious danger this time.",
  ui_story_5066_50660302_53_dialog_content = "You're right... We need to find her right away...",
  ui_story_5066_50660302_54_dialog_content = "And we have to find her before these guards do, or else things will get even worse.",
  ui_story_5066_50660401_1_dialog_content = "Huff, puff...",
  ui_story_5066_50660401_2_dialog_content = "I think... I lost them...",
  ui_story_5066_50660401_3_dialog_content = "Head this way! Search!",
  ui_story_5066_50660401_4_dialog_content = "Ah... Oh no...",
  ui_story_5066_50660401_5_dialog_content = "If I curl up and hide right here... They shouldn't be able to find me...",
  ui_story_5066_50660401_6_dialog_content = "My heart... It's beating so fast... I feel like I can't breathe...",
  ui_story_5066_50660401_7_dialog_content = "This way! Over here!",
  ui_story_5066_50660401_8_dialog_content = "Ahhh... Please don't find me, please don't find me, please don't find me...",
  ui_story_5066_50660401_9_dialog_content = "You didn't have to run, did you?",
  ui_story_5066_50660401_10_dialog_content = "...?!",
  ui_story_5066_50660401_11_dialog_content = "Make a pact with me, and all troubles will be gone.",
  ui_story_5066_50660401_12_dialog_content = "You, it's time to make a choice...",
  ui_story_5066_50660401_13_dialog_content = "B-But...",
  ui_story_5066_50660401_14_dialog_content = "Things are already like this; what's there to hesitate about?",
  ui_story_5066_50660401_15_dialog_content = "I-I know... But...",
  ui_story_5066_50660401_16_dialog_content = "<size=33>The idea of... getting involved with such a weird creature...</size>",
  ui_story_5066_50660401_17_dialog_content = "<size=33>It doesn't sound very pleasant either...</size>",
  ui_story_5066_50660401_18_dialog_content = "Loud and clear, I heard your words.",
  ui_story_5066_50660401_19_dialog_content = "Ah... I'm sorry! I... I didn't mean it like that...",
  ui_story_5066_50660401_20_dialog_content = "The guards went that way! Let's check things out over here!",
  ui_story_5066_50660401_21_dialog_content = "Right. I can feel it... She's close by...",
  ui_story_5066_50660401_22_dialog_content = "...",
  ui_story_5066_50660401_23_dialog_content = "Oh no, I spent too much time talking to that voice...",
  ui_story_5066_50660401_24_dialog_content = "I completely forgot about the danger around me...",
  ui_story_5066_50660401_25_dialog_content = "Sniff... D-Do I really have to become part of the prince's collection...?",
  ui_story_5066_50660401_26_dialog_content = "It's Connolly! We finally found her!",
  ui_story_5066_50660401_27_dialog_content = "Phew... Thank goodness... We got to her before those guys...",
  ui_story_5066_50660401_28_dialog_content = "Huh...?",
  ui_story_5066_50660401_29_dialog_content = "Are you okay, Connolly? They didn't hurt you, did they?",
  ui_story_5066_50660401_30_dialog_content = "I-It's you, Dayna... And Robyn too?",
  ui_story_5066_50660401_31_dialog_content = "... *nod*",
  ui_story_5066_50660401_32_dialog_content = "Oh, it's so nice to see you both! But I'm sorry... I really don't have time to help with your errands today...",
  ui_story_5066_50660401_33_dialog_content = "Now's not the time for that, Connolly.",
  ui_story_5066_50660401_34_dialog_content = "We need to get out of here before the prince's guards find you!",
  ui_story_5066_50660401_35_dialog_content = "How do you know about the prince? Oh no... Don't tell me this place isn't safe either?",
  ui_story_5066_50660401_36_dialog_content = "If they find me here... Wh-What should I do...?",
  ui_story_5066_50660401_37_dialog_content = "Don't worry... Dayna came up with a good idea...",
  ui_story_5066_50660401_38_dialog_content = "R... Really?",
  ui_story_5066_50660401_39_dialog_content = "Yep! We're gonna wait for those guards to show up, then give them wrong information and send them looking somewhere else.",
  ui_story_5066_50660401_40_dialog_content = "That should buy you enough time to find someplace safe to hide.",
  ui_story_5066_50660401_41_dialog_content = "Ah... Thank you so much, but... I don't know how to repay you two...",
  ui_story_5066_50660401_42_dialog_content = "Tch, not much point saying that, is there?",
  ui_story_5066_50660401_43_dialog_content = "You've been helping us for the longest time... We're the ones who haven't repaid you...",
  ui_story_5066_50660401_44_dialog_content = "But...",
  ui_story_5066_50660401_45_dialog_content = "Alright alright, save it for another time. You'll lose your chance if you don't get moving.",
  ui_story_5066_50660401_46_dialog_content = "Now go... And don't look back...",
  ui_story_5066_50660401_47_dialog_content = "G-Got it!",
  ui_story_5066_50660401_48_dialog_content = "Hurry up, you useless bunch! Why are you still dawdling here?",
  ui_story_5066_50660401_49_dialog_content = "The intel says she's in this alley, right? If it's wrong, you'll be facing consequences!",
  ui_story_5066_50660401_50_dialog_content = "Heh, guess we were too late.",
  ui_story_5066_50660401_51_dialog_content = "So... What should we do, Dayna?",
  ui_story_5066_50660401_52_dialog_content = "We have to block off the entrance to that alley, so that Connolly has enough time to escape.",
  ui_story_5066_50660401_53_dialog_content = "No matter what, we can't let them get their hands on her.",
  ui_story_5066_50660401_54_dialog_content = "Right.",
  ui_story_5066_50660401_55_dialog_content = "Um... J-Just a moment please...",
  ui_story_5066_50660401_56_dialog_content = "I'm... I'm really grateful for your help... Honestly...",
  ui_story_5066_50660401_57_dialog_content = "But you... You really don't have to go so far... for someone like me...",
  ui_story_5066_50660401_58_dialog_content = "I don't... want to make any trouble for either of you...",
  ui_story_5066_50660401_59_dialog_content = "Don't make us sound like strangers, Connolly! You're gonna hurt our feelings!",
  ui_story_5066_50660401_60_dialog_content = "Actually... We've wanted... to repay your kindness for a long time now...",
  ui_story_5066_50660401_61_dialog_content = "Yep, but you don't make it easy for us, since you're always hiding from everyone.",
  ui_story_5066_50660401_62_dialog_content = "Sometimes I worry that your aunt's locked you up, and it makes me want to go bust you out.",
  ui_story_5066_50660401_63_dialog_content = "So please... Let's help you this time...",
  ui_story_5066_50660401_64_dialog_content = "I'll go left and you go right. Let's go, Robyn.",
  ui_story_5066_50660401_65_dialog_content = "Okay, Dayna.",
  ui_story_5066_50660402_1_dialog_content = "Did I... Did I manage to escape...?",
  ui_story_5066_50660402_2_dialog_content = "Thank you, Dayna and Robyn...",
  ui_story_5066_50660402_3_dialog_content = "...",
  ui_story_5066_50660402_4_dialog_content = "For their sakes, I... I can't let myself get captured!",
  ui_story_5066_50660402_5_dialog_content = "*gasping* I... I think I should be safe here...",
  ui_story_5066_50660402_6_dialog_content = "...",
  ui_story_5066_50660402_7_dialog_content = "Ah...",
  ui_story_5066_50660402_8_dialog_content = "A passing guard? It looks like... he hasn't noticed me...",
  ui_story_5066_50660402_9_dialog_content = "Still... The king and the prince control this entire area... Where can I possibly hide around here?",
  ui_story_5066_50660402_10_dialog_content = "As much as I couldn't stand it... I can't even go back to the attic in my aunt's house...",
  ui_story_5066_50660402_11_dialog_content = "My cousin will just find a way to present me to the prince...",
  ui_story_5066_50660402_12_dialog_content = "...",
  ui_story_5066_50660402_13_dialog_content = "I'm not strong enough to fight them all on my own...",
  ui_story_5066_50660402_14_dialog_content = "Which means... I only have one choice left, don't I...?",
  ui_story_5066_50660402_15_dialog_content = "To call upon me, play it with your clarinet.",
  ui_story_5066_50660402_16_dialog_content = "I'm really about to play it... I'm still so nervous...",
  ui_story_5066_50660402_17_dialog_content = "But Mama did leave me with this clarinet, after all...",
  ui_story_5066_50660402_18_dialog_content = "I have to... be brave...",
  ui_story_5066_50660402_19_dialog_content = "*plays the clarinet*",
  ui_story_5066_50660402_20_dialog_content = "...",
  ui_story_5066_50660402_21_dialog_content = "I'm pleased to see you finally make a decision...",
  ui_story_5066_50660402_22_dialog_content = "Come and make a pact with me now!",
  ui_story_5066_50660402_23_dialog_content = "C-Could I please have a second...?",
  ui_story_5066_50660402_24_dialog_content = "At this point, there's no turning back for you.",
  ui_story_5066_50660402_25_dialog_content = "I... I won't regret anything, but... I just want to make sure of something first.",
  ui_story_5066_50660402_26_dialog_content = "You're not... going to make me do something terrible, right?",
  ui_story_5066_50660402_27_dialog_content = "My ultimate goal is for you to be the queen, ruling the entire underwater realm.",
  ui_story_5066_50660402_28_dialog_content = "Terrible or not, it's all up to your own choice.",
  ui_story_5066_50660402_29_dialog_content = "But... If I become a queen or whatever... Won't I stand out too much?",
  ui_story_5066_50660402_30_dialog_content = "I just... don't want to do anything too noticeable...",
  ui_story_5066_50660402_31_dialog_content = "An odd request... I thought if anyone could harness my power, they'd want to flaunt their strength to the world.",
  ui_story_5066_50660402_32_dialog_content = "But you... Well, it's not a big deal; you can definitely be a low-profile queen if that's what you want.",
  ui_story_5066_50660402_33_dialog_content = "O-Okay then. Go ahead and... take whatever price you want from me...",
  ui_story_5066_50660402_34_dialog_content = "Price?",
  ui_story_5066_50660402_35_dialog_content = "Aren't you going to take my eyes or my nose? ... Or maybe you want my ears?",
  ui_story_5066_50660402_36_dialog_content = "*sniffling* I don't care if you have to eat me... As long as I can get out of this dangerous situation...",
  ui_story_5066_50660402_37_dialog_content = "I've said it before... I never consume mortal beings!",
  ui_story_5066_50660402_38_dialog_content = "Boo-hoo! I... I'm sorry! I totally forgot...",
  ui_story_5066_50660402_39_dialog_content = "I don't need you to pay any price.",
  ui_story_5066_50660402_40_dialog_content = "Making a pact with you is only because of your uniqueness and the relic you hold.",
  ui_story_5066_50660402_41_dialog_content = "When the clarinet's music sheet is played, I'll help you rule the seas.",
  ui_story_5066_50660402_42_dialog_content = "With that said, do you have any doubts left in your mind?",
  ui_story_5066_50660402_43_dialog_content = "Oh... I guess not...",
  ui_story_5066_50660402_44_dialog_content = "But isn't this... Too good to be true...?",
  ui_story_5066_50660402_45_dialog_content = "No need to worry; you're about to embark on a brand-new chapter in life. Enjoy it to the fullest.",
  ui_story_5066_50660402_46_dialog_content = "<size=45>At this moment, the pact is formally made!</size>",
  ui_story_5066_50660402_47_dialog_content = "...",
  ui_story_5066_50660501_1_dialog_content = "<color=#e8d9bb>Clang—Clang—</color>",
  ui_story_5066_50660501_2_dialog_content = "These guards are tougher than I thought.",
  ui_story_5066_50660501_3_dialog_content = "Go choke on some kelp, you jerks!",
  ui_story_5066_50660501_4_dialog_content = "<color=#e8d9bb>Clang—Crack—</color>",
  ui_story_5066_50660501_5_dialog_content = "You're not wrong... They're pretty persistent...",
  ui_story_5066_50660501_6_dialog_content = "But we can't let them get past us...",
  ui_story_5066_50660501_7_dialog_content = "Huh, that's quite a surprise.",
  ui_story_5066_50660501_8_dialog_content = "In these waters, there are actually ones daring to defy me and my guards!?",
  ui_story_5066_50660501_9_dialog_content = "Looks like my visit here today is well-timed!",
  ui_story_5066_50660501_10_dialog_content = "If we let this slide, who knows what kind of trouble might brew?",
  ui_story_5066_50660501_11_dialog_content = "Guards, are you starving or somethin'? Hurry up and take down these two traitors!",
  ui_story_5066_50660501_12_dialog_content = "<color=#e8d9bb>Clang—Crack—</color>",
  ui_story_5066_50660501_13_dialog_content = "You're a thousand years too early to be challenging me!",
  ui_story_5066_50660501_14_dialog_content = "But I was getting a little bored, so let's have some fun!",
  ui_story_5066_50660501_15_dialog_content = "<color=#e8d9bb>Clang—Crack—</color>",
  ui_story_5066_50660501_16_dialog_content = "Fighting... Isn't really an issue for us...",
  ui_story_5066_50660501_17_dialog_content = "I just wish I knew how Connolly is doing right now...",
  ui_story_5066_50660501_18_dialog_content = "<color=#e8d9bb>The sound of a clarinet rings out.</color>",
  ui_story_5066_50660501_19_dialog_content = "What's the deal with this eerie tune?",
  ui_story_5066_50660501_20_dialog_content = "Hey, guards, go and investigate...",
  ui_story_5066_50660501_21_dialog_content = "...",
  ui_story_5066_50660501_22_dialog_content = "<size=45>What... what's this?!</size>",
  ui_story_5066_50660501_23_dialog_content = "Is that Connolly? What happened to her?!",
  ui_story_5066_50660501_24_dialog_content = "It looks like... She gained some new powers... Did she do this just to help us?",
  ui_story_5066_50660501_25_dialog_content = "Hah! All bluffing; it just looks scary.",
  ui_story_5066_50660501_26_dialog_content = "It actually saved me the trouble. Come on, guards, go get her!",
  ui_story_5066_50660501_27_dialog_content = "*plays a tune*",
  ui_story_5066_50660501_28_dialog_content = "Huh... Aaaaah... what are these tentacles?!",
  ui_story_5066_50660501_29_dialog_content = "No! Please! Put me down!",
  ui_story_5066_50660501_30_dialog_content = "*plays a tune*",
  ui_story_5066_50660501_31_dialog_content = "I don't intend to do it... I'm just following the prince's orders... Please, spare me!",
  ui_story_5066_50660501_32_dialog_content = "I don't want to fight you either! It's... it's all because of the prince! He made me do it!",
  ui_story_5066_50660501_33_dialog_content = "Stop! Who said you could run away?! You useless bunch, stop! Dammit...",
  ui_story_5066_50660501_34_dialog_content = "...",
  ui_story_5066_50660501_35_dialog_content = "Heh heh. Good, very good...",
  ui_story_5066_50660501_36_dialog_content = "Dare to defy me, and you shall certainly pay the price!",
  ui_story_5066_50660501_37_dialog_content = "Anyway, the taxes this rundown little town pays are pitifully low to begin with.",
  ui_story_5066_50660501_38_dialog_content = "If you still don't comply, I don't see a reason for this town's existence!",
  ui_story_5066_50660501_39_dialog_content = "...",
  ui_story_5066_50660501_40_dialog_content = "Hey, you... weird-looking girl, enough is enough!",
  ui_story_5066_50660501_41_dialog_content = "If the prince goes back and tells the king to send an army to destroy our town... can you bear the consequences?",
  ui_story_5066_50660501_42_dialog_content = "Moreover, the one you've offended is none other than the noble Prince!",
  ui_story_5066_50660501_43_dialog_content = "You, with your lowly status, how can you act so disrespectfully?",
  ui_story_5066_50660501_44_dialog_content = "...",
  ui_story_5066_50660501_45_dialog_content = "(I knew it... Standing out like this really doesn't suit me...)",
  ui_story_5066_50660501_46_dialog_content = "(I... screwed up again, didn't I...?)",
  ui_story_5066_50660501_47_dialog_content = "(If I only worry about the danger at hand... Will the consequences keep being this bad...?)",
  ui_story_5066_50660501_48_dialog_content = "I... I didn't mean to do that... B-But...",
  ui_story_5066_50660501_49_dialog_content = "Hey, Connolly! You don't need to apologize to these jerks at all!",
  ui_story_5066_50660501_50_dialog_content = "Did you forget about how that pompous prince attacked you? Why are you still afraid of him?!",
  ui_story_5066_50660501_51_dialog_content = "You're gonna get picked on for the rest of your life if you don't change!",
  ui_story_5066_50660501_52_dialog_content = "Tolerance and compromise... will only get you so far...",
  ui_story_5066_50660501_53_dialog_content = "That much is undeniable...",
  ui_story_5066_50660501_54_dialog_content = "That's right! Just look at all the outrageous stuff the prince has done in this little town!",
  ui_story_5066_50660501_55_dialog_content = "If he doesn't wanna rule over us, that's fine by me!",
  ui_story_5066_50660501_56_dialog_content = "It's about time we picked a new ruler anyway!",
  ui_story_5066_50660501_57_dialog_content = "...",
  ui_story_5066_50660501_58_dialog_content = "<size=33>Well, I think... what she said actually makes sense...</size>",
  ui_story_5066_50660501_59_dialog_content = "<size=33>Honestly, I've had enough too...</size>",
  ui_story_5066_50660501_60_dialog_content = "If they hike up the taxes again, we won't survive; it'll be a dead end anyway.",
  ui_story_5066_50660501_61_dialog_content = "If possible, we might as well get a new ruler, right?",
  ui_story_5066_50660501_62_dialog_content = "<size=45>Outrageous, you're all being outrageous!</size>",
  ui_story_5066_50660501_63_dialog_content = "To think you lowly folks could shake our reign with a few words? That's not gonna happen!",
  ui_story_5066_50660501_64_dialog_content = "Today, I'll make an example and execute all you rebels who speak out of turn!",
  ui_story_5066_50660501_65_dialog_content = "Um... I'm the one who caused this whole mess...",
  ui_story_5066_50660501_66_dialog_content = "Everyone was speaking for me just now...",
  ui_story_5066_50660501_67_dialog_content = "But now that I have this incredible power... I... I'm not the same as I used to be...",
  ui_story_5066_50660501_68_dialog_content = "This time... It's my turn to protect everyone!",
  ui_story_5066_50660602_1_dialog_content = "<color=#e8d9bb>Smack—Smack!</color>",
  ui_story_5066_50660602_2_dialog_content = "Ah... it hurts...",
  ui_story_5066_50660602_3_dialog_content = "<color=#e8d9bb>Smack—Smack!</color>",
  ui_story_5066_50660602_4_dialog_content = "Eek... no, please, stop!",
  ui_story_5066_50660602_5_dialog_content = "*plays a tune*",
  ui_story_5066_50660602_6_dialog_content = "Enough... That's enough!",
  ui_story_5066_50660602_7_dialog_content = "I lost! I surrender! No... I didn't lose to you...",
  ui_story_5066_50660602_8_dialog_content = "I lost to this tentacle monster!",
  ui_story_5066_50660602_9_dialog_content = "Where on earth did you acquire such power!?",
  ui_story_5066_50660602_10_dialog_content = "Well... uh, I don't know how to explain this...",
  ui_story_5066_50660602_11_dialog_content = "Maybe it would be better for you to see it for yourselves?",
  ui_story_5066_50660602_12_dialog_content = "*plays a tune*",
  ui_story_5066_50660602_13_dialog_content = "...",
  ui_story_5066_50660602_14_dialog_content = "...?!",
  ui_story_5066_50660602_15_dialog_content = "What?! It's...!",
  ui_story_5066_50660602_16_dialog_content = "Could it be... the one from the ancient legend, the temple...",
  ui_story_5066_50660602_17_dialog_content = "No, no, no, absolutely impossible! How could this peculiar-looking girl...",
  ui_story_5066_50660602_18_dialog_content = "<color=#e8d9bb>Smack—Smack!</color>",
  ui_story_5066_50660602_19_dialog_content = "<color=#e8d9bb>Sploosh—</color>",
  ui_story_5066_50660602_20_dialog_content = "Ugh... Urgh...",
  ui_story_5066_50660602_21_dialog_content = "How dare... How dare you... Just wait, the kingdom's army will come here... to settle the score and wash away my shame!",
  ui_story_5066_50660602_22_dialog_content = "Phew... I think I finally took care of them... right?",
  ui_story_5066_50660602_23_dialog_content = "Of course you did, Connolly! The way you sent the prince flying was so awesome! Have some self-confidence!",
  ui_story_5066_50660602_24_dialog_content = "It's true... Not even Dayna could have done something like that...",
  ui_story_5066_50660602_25_dialog_content = "I... It wasn't that impressive... Please don't make fun of me, you two...",
  ui_story_5066_50660602_26_dialog_content = "We aren't making fun of you at all.",
  ui_story_5066_50660602_27_dialog_content = "So what in the world is that thing, Connolly? Some kind of monster?",
  ui_story_5066_50660602_28_dialog_content = "Dayna... That might have been... A little rude...",
  ui_story_5066_50660602_29_dialog_content = "Whoops, sorry about that! It's more like your friend, right?",
  ui_story_5066_50660602_30_dialog_content = "Uh... To be honest, I don't really know what it is either...",
  ui_story_5066_50660602_31_dialog_content = "But it keeps calling itself \"the great Aqua Lord.\"",
  ui_story_5066_50660602_32_dialog_content = "So I figure... It must be a pretty powerful figure of some sort, right?",
  ui_story_5066_50660602_33_dialog_content = "<size=45>Aqua Lord? It's the... Aqua Lord?!</size>",
  ui_story_5066_50660602_34_dialog_content = "Huh? Pardon me... Are you familiar with the Aqua Lord?",
  ui_story_5066_50660602_35_dialog_content = "Aqua Lord... He was the great ruler who once dominated the underwater world!",
  ui_story_5066_50660602_36_dialog_content = "Before the brutal Merman King came to the shallow waters, it used to rule over everything here...",
  ui_story_5066_50660602_37_dialog_content = "Rumor has it that to this day, the remains of its temple with hidden power still exist.",
  ui_story_5066_50660602_38_dialog_content = "<anim type=Shake>ç åï|'H>■...</anim>",
  ui_story_5066_50660602_39_dialog_content = "The holy words, it's the holy words! Lord is about to impart the holy words to us...",
  ui_story_5066_50660602_40_dialog_content = "...",
  ui_story_5066_50660602_41_dialog_content = "<color=#e8d9bb>Thud—</color>",
  ui_story_5066_50660602_42_dialog_content = "<color=#e8d9bb>With a look of unwavering faith, the old man kneels down in reverence...</color>",
  ui_story_5066_50660602_43_dialog_content = "<color=#e8d9bb>Like a wave, the rest of the undersea denizens begin to prostrate themselves before this once-great ruler...</color>",
  ui_story_5066_50660701_1_dialog_content = "It's all your fault for sending Connolly to run errands, and now it's turned into a total disaster!",
  ui_story_5066_50660701_2_dialog_content = "How could I have known she would... dare to be so reckless and defiant?",
  ui_story_5066_50660701_3_dialog_content = "If this affects our son's career, no way you can ever make it up.",
  ui_story_5066_50660701_4_dialog_content = "Stop talking about it; just stop! This cursed jinx, once we find her, we'll need to give her a good lesson!",
  ui_story_5066_50660701_5_dialog_content = "...",
  ui_story_5066_50660701_6_dialog_content = "What's going on? Why is everyone kneeling on the ground?",
  ui_story_5066_50660701_7_dialog_content = "Look... look over there.",
  ui_story_5066_50660701_8_dialog_content = "<anim type=Shake>âŠâ €په؛‹Šèã</anim>",
  ui_story_5066_50660701_9_dialog_content = "That is... I've heard about it. That's the Great Lord of the old!",
  ui_story_5066_50660701_10_dialog_content = "And beside the lord is... Connolly?! How's that possible?",
  ui_story_5066_50660701_11_dialog_content = "Don't worry about whether it is possible or not. Kneel down quickly, or it'll be us in trouble!",
  ui_story_5066_50660701_12_dialog_content = "<color=#e8d9bb>Thud—</color>",
  ui_story_5066_50660701_13_dialog_content = "<anim type=Shake>е­‘гдё —пе›Œâ€¦в¦</anim>",
  ui_story_5066_50660701_14_dialog_content = "Even though there were a lot of different voices coming from the crowd just now...",
  ui_story_5066_50660701_15_dialog_content = "It looks like everyone more or less accepts this Aqua Lord.",
  ui_story_5066_50660701_16_dialog_content = "The problem, it seems... Is that no one can understand what it's saying.",
  ui_story_5066_50660701_17_dialog_content = "We may not be able to understand, but it shouldn't be a problem for Connolly!",
  ui_story_5066_50660701_18_dialog_content = "Mind translating for us?",
  ui_story_5066_50660701_19_dialog_content = "Oh... I didn't realize no one else could understand...",
  ui_story_5066_50660701_20_dialog_content = "Its speech has the same effect as the melody of that music score from before...",
  ui_story_5066_50660701_21_dialog_content = "Could this be... why it chose me?",
  ui_story_5066_50660701_22_dialog_content = "W-Well... If no one objects...",
  ui_story_5066_50660701_23_dialog_content = "I'll translate the Aqua Lord's words for everyone to hear...",
  ui_story_5066_50660701_24_dialog_content = "<anim type=Shake>éµè Œâ€...¦â€¦ å“š■</anim>",
  ui_story_5066_50660701_25_dialog_content = "The Aqua Lord says that it wishes to return to this world and reclaim this town from the usurping Merman King.",
  ui_story_5066_50660701_26_dialog_content = "<anim type=Shake>FzI¦م€ ...■چcJ;@ڑ â– é‡Œ</anim>",
  ui_story_5066_50660701_27_dialog_content = "And... Because of my innate ability to communicate with it, the Aqua Lord formed a pact with me...",
  ui_story_5066_50660701_28_dialog_content = "To serve as its messenger and carry out its will...",
  ui_story_5066_50660701_29_dialog_content = "<anim type=Shake>â€¦â€¦و°i%µç·tu€¦â€i... €¦â€¦وˆگم€■</anim>",
  ui_story_5066_50660701_30_dialog_content = "Huh...?!",
  ui_story_5066_50660701_31_dialog_content = "(Uh-oh...)",
  ui_story_5066_50660701_32_dialog_content = "(It wants me to tell everyone... That I'm the Aqua Queen...?)",
  ui_story_5066_50660701_33_dialog_content = "(I don't think... I can say something like that...)",
  ui_story_5066_50660701_34_dialog_content = "(I already said... That I don't want to do anything that'll make me stand out...)",
  ui_story_5066_50660701_35_dialog_content = "<anim type=Shake>еâ€...eåŸœ■å€âŠâ</anim>",
  ui_story_5066_50660701_36_dialog_content = "<size=33>That's enough, Aqua Lord... Any more demands and you'll just scare everyone...</size>",
  ui_story_5066_50660701_37_dialog_content = "... (displeased)",
  ui_story_5066_50660701_38_dialog_content = "Um... Uh...",
  ui_story_5066_50660701_39_dialog_content = "I-Is it alright... If I stop translating now?",
  ui_story_5066_50660701_40_dialog_content = "...",
  ui_story_5066_50660701_41_dialog_content = "Of course, Speaker of the Divine! Or should we address you as... the Queen?",
  ui_story_5066_50660701_42_dialog_content = "<size=45>Uhhh... Queen?!</size>",
  ui_story_5066_50660701_43_dialog_content = "Th-That's a little bold, don't you think...?",
  ui_story_5066_50660701_44_dialog_content = "<size=33>I didn't even translate that last part, but somehow... Everyone has already started... to call me \"queen\"?</size>",
  ui_story_5066_50660701_45_dialog_content = "That's right, Your Majesty, your power is evident to all!",
  ui_story_5066_50660701_46_dialog_content = "Those despicable Merman guards are lingering around. You should really teach them a lesson!",
  ui_story_5066_50660701_47_dialog_content = "You have our full support!",
  ui_story_5066_50660701_48_dialog_content = "Oh... Well, if things are going to be like this...",
  ui_story_5066_50660701_49_dialog_content = "Even if I wasn't doing it for anyone else's sake, or even my own...",
  ui_story_5066_50660701_50_dialog_content = "I would still want to finish cleaning up around here...",
  ui_story_5066_50660702_1_dialog_content = "<color=#e8d9bb>Smack—Smack!</color>",
  ui_story_5066_50660702_2_dialog_content = "Phew... That was the last of them. Those Merman guards should be gone now...",
  ui_story_5066_50660702_3_dialog_content = "Those stinkin' thugs should've been run out of town ages ago!",
  ui_story_5066_50660702_4_dialog_content = "Unfortunately, Connolly's cookies didn't make it. What a downer...",
  ui_story_5066_50660702_5_dialog_content = "Hey Connolly... You don't seem particularly happy... Is everything okay?",
  ui_story_5066_50660702_6_dialog_content = "Oh, sorry! You could tell just by looking, huh...?",
  ui_story_5066_50660702_7_dialog_content = "Just now... Everyone started calling me their queen...",
  ui_story_5066_50660702_8_dialog_content = "But... I don't want to be this kind of weird queen...",
  ui_story_5066_50660702_9_dialog_content = "I... I would rather spend my days alone in the attic, with nothing but my music to keep me company...",
  ui_story_5066_50660702_10_dialog_content = "I don't really get it, but I wholeheartedly support your decision.",
  ui_story_5066_50660702_11_dialog_content = "But... The Merman...",
  ui_story_5066_50660702_12_dialog_content = "It's fine, Robyn. Don't scare Connolly.",
  ui_story_5066_50660702_13_dialog_content = "It's okay... I'm aware of the situation I'm in...",
  ui_story_5066_50660702_14_dialog_content = "The Merman King... He won't let me go so easily, will he?",
  ui_story_5066_50660702_15_dialog_content = "...",
  ui_story_5066_50660702_16_dialog_content = "Tsk, don't worry! Robyn and I will protect you!",
  ui_story_5066_50660702_17_dialog_content = "That's right... After all, you've always been so kind to us.",
  ui_story_5066_50660702_18_dialog_content = "We meant to repay you just now, but you ended up saving us again...",
  ui_story_5066_50660702_19_dialog_content = "But... But I was just doing my duty.",
  ui_story_5066_50660702_20_dialog_content = "The Aqua Lord helped me when I was in danger... So I have to repay it by carrying out its wishes...",
  ui_story_5066_50660702_21_dialog_content = "After all... It didn't take anything from me when we formed our pact...",
  ui_story_5066_50660702_22_dialog_content = "Its wishes? You mean you're going to help it retake this town?!",
  ui_story_5066_50660702_23_dialog_content = "Yes... So could you please tell me everything you know about the Merman King?",
  ui_story_5066_50660702_24_dialog_content = "Of course! Robyn's better at explaining this stuff, so I'll let her do it.",
  ui_story_5066_50660702_25_dialog_content = "Alright Dayna, but you still need to help me fill in the gaps...",
  ui_story_5066_50660702_26_dialog_content = "I guess we should start from the very beginning.",
  ui_story_5066_50660702_27_dialog_content = "The Merman King is... A lofty man who first came from the Shallows...",
  ui_story_5066_50660702_28_dialog_content = "And proclaimed himself ruler of all fishkind.",
  ui_story_5066_50660702_29_dialog_content = "The guy's a firm believer in the supremacy of the Shallows, so he looks down on all the other races living on the ocean floor.",
  ui_story_5066_50660702_30_dialog_content = "That's why he resorts to cruelty and violence when ruling over small towns like this.",
  ui_story_5066_50660702_31_dialog_content = "It's also why... He rarely shows himself around here.",
  ui_story_5066_50660702_32_dialog_content = "The Merman Prince, on the other hand... Is his successor, as well as the person he appointed to collect taxes from us.",
  ui_story_5066_50660702_33_dialog_content = "Even though the prince comes across as an idiot...",
  ui_story_5066_50660702_34_dialog_content = "We can't forget that he's a distinguished person from the Shallows, an area rich in resources and advanced technology...",
  ui_story_5066_50660702_35_dialog_content = "His craftiness and weaponry shouldn't be underestimated.",
  ui_story_5066_50660702_36_dialog_content = "Which also means the Merman King is even more scary.",
  ui_story_5066_50660702_37_dialog_content = "Didn't you just say not to scare her...?",
  ui_story_5066_50660702_38_dialog_content = "I mean if we're going off to fight, then there's really no point in beating around the bush anymore.",
  ui_story_5066_50660702_39_dialog_content = "Boo-hoo...",
  ui_story_5066_50660702_40_dialog_content = "I... I'm really grateful to both of you for telling me all of this...",
  ui_story_5066_50660702_41_dialog_content = "But... Do I really stand a chance against someone as powerful as the Merman King?",
  ui_story_5066_50660702_42_dialog_content = "...",
  ui_story_5066_50660702_43_dialog_content = "Don't be afraid, Connolly. You and the Aqua Lord are far stronger than all of them...",
  ui_story_5066_50660702_44_dialog_content = "Not only that, we'll always be by your side...",
  ui_story_5066_50660702_45_dialog_content = "That's right! We'll just wait for you to become the Queen!",
  ui_story_5066_50660702_46_dialog_content = "And when that day comes, we'll serve as your royal guards!",
  ui_story_5066_50660702_47_dialog_content = "One at your left... And one at your right.",
  ui_story_5066_50660702_48_dialog_content = "Never too far from your side...",
  ui_story_5066_50660702_49_dialog_content = "That way we can help you out whenever you need it, right?",
  ui_story_5066_50660702_50_dialog_content = "We'd also be helping you retake control of this town!",
  ui_story_5066_50660702_51_dialog_content = "You can't leave me out if you're gonna do something cool like that!",
  ui_story_5066_50660702_52_dialog_content = "Besides, I've been wanting to wipe that arrogant look off the king's face for a while now!",
  ui_story_5066_50660702_53_dialog_content = "Everyone... I really don't know... How I could ever repay you...",
  ui_story_5066_50660702_54_dialog_content = "But with your help, I know I would have nothing to fear.",
  ui_story_5066_50660702_55_dialog_content = "So please... Please lend me your strength...!",
  ui_story_5066_50660801_1_dialog_content = "*plays the clarinet*",
  ui_story_5066_50660801_2_dialog_content = "...",
  ui_story_5066_50660801_3_dialog_content = "Eek! ... Even though this isn't my first time summoning it, I still can't help but feel a little scared...",
  ui_story_5066_50660801_4_dialog_content = "Um... S-Sorry for summoning you again so soon...",
  ui_story_5066_50660801_5_dialog_content = "I just wanted to tell you... that I'm ready and willing to carry out your wishes.",
  ui_story_5066_50660801_6_dialog_content = "I am deeply pleased with your decision.",
  ui_story_5066_50660801_7_dialog_content = "So, let's make this pact official.",
  ui_story_5066_50660801_8_dialog_content = "Huh...? But I thought we already formed our pact?",
  ui_story_5066_50660801_9_dialog_content = "I am the ancient... and great Aqua Lord. A temporary pact on the battlefield is merely an emergency measure.",
  ui_story_5066_50660801_10_dialog_content = "It does not befit my esteemed status.",
  ui_story_5066_50660801_11_dialog_content = "Oh... Okay. So how should we do it...?",
  ui_story_5066_50660801_12_dialog_content = "With your clarinet as the relic, let's formalize it.",
  ui_story_5066_50660801_13_dialog_content = "This way, I can always be by your side.",
  ui_story_5066_50660801_14_dialog_content = "Okay then, like this...?",
  ui_story_5066_50660801_15_dialog_content = "*plays a tune*",
  ui_story_5066_50660801_16_dialog_content = "Very well, this constitutes the official pact.",
  ui_story_5066_50660801_17_dialog_content = "Being the Queen, it's your duty to manage the town on my behalf.",
  ui_story_5066_50660801_18_dialog_content = "Oh... I'll do my best, even though I've never done anything like this before...",
  ui_story_5066_50660801_19_dialog_content = "Also, rebuild the temple.",
  ui_story_5066_50660801_20_dialog_content = "To restore my power to defend against the incoming attack from the Merman King.",
  ui_story_5066_50660801_21_dialog_content = "Uh... What temple?",
  ui_story_5066_50660801_22_dialog_content = "I mentioned this before, but you... didn't interpret it.",
  ui_story_5066_50660801_23_dialog_content = "I don't know how to put it... it sounds like we're going to labor everyone.",
  ui_story_5066_50660801_24_dialog_content = "But... I promise I'll figure something out...",
  ui_story_5066_50660801_25_dialog_content = "So, uh... What kind of temple do you want?",
  ui_story_5066_50660801_26_dialog_content = "To honor me, the great Aqua Lord, there are requirements about the scale of my temple, which you must keep in your mind.",
  ui_story_5066_50660801_27_dialog_content = "G-Got it!",
  ui_story_5066_50660801_28_dialog_content = "Firstly, it should be as grand as the church where the nocturnal demon resides.",
  ui_story_5066_50660801_29_dialog_content = "The \"nocturnal demon\"? Hmm... A grand temple... Uh-huh, got it.",
  ui_story_5066_50660801_30_dialog_content = "It should be as mysterious as the House of the Witch...",
  ui_story_5066_50660801_31_dialog_content = "\"As mysterious as a witch's house...\"",
  ui_story_5066_50660801_32_dialog_content = "Yes, that should fit pretty well!",
  ui_story_5066_50660801_33_dialog_content = "It should possess the ancient charm of a heretical castle.",
  ui_story_5066_50660801_34_dialog_content = "An ancient castle? You have good taste in architecture, Aqua Lord...",
  ui_story_5066_50660801_35_dialog_content = "It should gleam in the dark like a Shining Trapezohedron.",
  ui_story_5066_50660801_36_dialog_content = "A glow-in-the-dark temple... Sounds like something out of a fairy tale, but I kind of like that...",
  ui_story_5066_50660801_37_dialog_content = "That should be all... Do you understand it entirely?",
  ui_story_5066_50660801_38_dialog_content = "I thought it would be a lot more complicated than this... But it's not too hard to understand!",
  ui_story_5066_50660801_39_dialog_content = "So, uh... You want a big, ancient, magical, glow-in-the-dark castle, right?",
  ui_story_5066_50660801_40_dialog_content = "...?",
  ui_story_5066_50660801_41_dialog_content = "I don't have much experience when it comes to this stuff... But please believe me...",
  ui_story_5066_50660801_42_dialog_content = "And I promise you... I'll build a temple that you can be proud of!",
  ui_story_5066_50660801_43_dialog_content = "I hope you can fulfill the promise.",
  ui_story_5066_50660801_44_dialog_content = "Okay...",
  ui_story_5066_50660801_45_dialog_content = "What's wrong, Connolly?",
  ui_story_5066_50660801_46_dialog_content = "You just formed an official pact with the Aqua Lord... But you don't seem too happy?",
  ui_story_5066_50660801_47_dialog_content = "Well, it did just give me a really hard quest...",
  ui_story_5066_50660801_48_dialog_content = "Managing a town, building a temple... I've never done any of this before...",
  ui_story_5066_50660801_49_dialog_content = "That's no reason to worry! You just haven't tried, that's all!",
  ui_story_5066_50660801_50_dialog_content = "Once you try, you'll find that it's not as hard as you thought. You've always had that kind of talent.",
  ui_story_5066_50660801_51_dialog_content = "Not only that... We and the townsfolk will help you however we can...",
  ui_story_5066_50660801_52_dialog_content = "If it means shaking off the Merman King's rule... I'm sure everyone will be excited to help.",
  ui_story_5066_50660801_53_dialog_content = "That's right, and all you need to do is answer their expectations.",
  ui_story_5066_50660801_54_dialog_content = "R... Really?",
  ui_story_5066_50660801_55_dialog_content = "Then... I'll try with everything I've got too...",
  ui_story_5066_50660801_56_dialog_content = "<color=#e8d9bb>Thud—</color>",
  ui_story_5066_50660801_57_dialog_content = "Your Majesty, I beg your forgiveness!",
  ui_story_5066_50660801_58_dialog_content = "My forgiveness? My son was subjected to such cruelty, and...",
  ui_story_5066_50660801_59_dialog_content = "The one who attacked him; it was your cousin, wasn't it?",
  ui_story_5066_50660801_60_dialog_content = "Well... that's just a freak our family adopted, essentially... we're not related!",
  ui_story_5066_50660801_61_dialog_content = "Well, if that's the case, you have no value to me either. Guards...",
  ui_story_5066_50660801_62_dialog_content = "Wait! I know her weakness... If you go to war, I can guarantee your victory!",
  ui_story_5066_50660801_63_dialog_content = "...?",
  ui_story_5066_50660801_64_dialog_content = "Go on, I'm listening.",
  ui_story_5066_50660801_65_dialog_content = "She's... just a regular girl. It's the clarinet's power that makes her so formidable.",
  ui_story_5066_50660801_66_dialog_content = "I... I, as her cousin, can help you steal the clarinet!",
  ui_story_5066_50660801_67_dialog_content = "Then, the town's residents would be nothing more than a ragtag bunch at your mercy.",
  ui_story_5066_50660801_68_dialog_content = "Are you telling the truth?",
  ui_story_5066_50660801_69_dialog_content = "Absolutely true, Your Majesty.",
  ui_story_5066_50660801_70_dialog_content = "Very well, I'll give you a chance to do it, but if it doesn't work out...",
  ui_story_5066_50660801_71_dialog_content = "I'm willing to accept the punishment!",
  ui_story_5066_50660901_1_dialog_content = "Phew... I'm finally done with today's work...",
  ui_story_5066_50660901_2_dialog_content = "Just dealing with all of the people's problems... Was enough to make my head spin...",
  ui_story_5066_50660901_3_dialog_content = "Noo-hoo... How am I supposed to build a temple on top of everything...?",
  ui_story_5066_50660901_4_dialog_content = "I miss my attic... And my music...",
  ui_story_5066_50660901_5_dialog_content = "Great work today, Connolly!",
  ui_story_5066_50660901_6_dialog_content = "You too, Dayna...",
  ui_story_5066_50660901_7_dialog_content = "Without you and Robyn... I don't know what I would do...",
  ui_story_5066_50660901_8_dialog_content = "Don't be so humble... In my opinion, you're doing a fantastic job as the Aqua Lord's messenger.",
  ui_story_5066_50660901_9_dialog_content = "Huh... R-Really...?",
  ui_story_5066_50660901_10_dialog_content = "But if you two weren't here... I wouldn't even have the courage to talk to the townspeople...",
  ui_story_5066_50660901_11_dialog_content = "That's fine. We're all good at different things, after all.",
  ui_story_5066_50660901_12_dialog_content = "And we'll help you... with the things you're not good at...",
  ui_story_5066_50660901_13_dialog_content = "Especially the fighting! Leave that stuff to us!",
  ui_story_5066_50660901_14_dialog_content = "I understand.... Thank you both for encouraging me...",
  ui_story_5066_50660901_15_dialog_content = "Then if there's nothing else for today, we'll be leaving now.",
  ui_story_5066_50660901_16_dialog_content = "Get plenty of rest, Connolly... After all, tomorrow... should be pretty busy too...",
  ui_story_5066_50660901_17_dialog_content = "Uh-huh... Will do.",
  ui_story_5066_50660901_18_dialog_content = "...",
  ui_story_5066_50660901_19_dialog_content = "*dazed* Hmm...",
  ui_story_5066_50660901_20_dialog_content = "...",
  ui_story_5066_50660901_21_dialog_content = "Ah...! A-Aqua Lord...?",
  ui_story_5066_50660901_22_dialog_content = "Please don't appear behind me so suddenly... You really scared me...",
  ui_story_5066_50660901_23_dialog_content = "I'm just concerned about the construction progress of my temple.",
  ui_story_5066_50660901_24_dialog_content = "Oh... Uh... About that...",
  ui_story_5066_50660901_25_dialog_content = "I don't understand...",
  ui_story_5066_50660901_26_dialog_content = "Huh? What do you mean...?",
  ui_story_5066_50660901_27_dialog_content = "You already possess absolute, formidable power.",
  ui_story_5066_50660901_28_dialog_content = "Simply employ your power to make these underwater residents build my temple and fend off the enemy for you.",
  ui_story_5066_50660901_29_dialog_content = "So, why do you bother so much about their lives?",
  ui_story_5066_50660901_30_dialog_content = "Um... Is that how you used to rule the undersea people, Aqua Lord?",
  ui_story_5066_50660901_31_dialog_content = "Is there anything wrong with it?",
  ui_story_5066_50660901_32_dialog_content = "Well, these people... They all have their own thoughts and emotions. They're living beings, not tools...",
  ui_story_5066_50660901_33_dialog_content = "The reason they're so dissatisfied with the Merman King right now is because he also treats them like expendable goods...",
  ui_story_5066_50660901_34_dialog_content = "If we treat them the exact same way... They won't support us the same way they're supporting us now.",
  ui_story_5066_50660901_35_dialog_content = "...",
  ui_story_5066_50660901_36_dialog_content = "Um... Do you... understand what I'm trying to say?",
  ui_story_5066_50660901_37_dialog_content = "I believe in absolute power, and your words cannot convince me...",
  ui_story_5066_50660901_38_dialog_content = "Oh... Then how should I explain...?",
  ui_story_5066_50660901_39_dialog_content = "Ah... I got it...",
  ui_story_5066_50660901_40_dialog_content = "We used to communicate through this clarinet before... Right?",
  ui_story_5066_50660901_41_dialog_content = "Then let me play you a song called \"Home.\"",
  ui_story_5066_50660901_42_dialog_content = "It's my favorite song. My mama taught it to me long ago...",
  ui_story_5066_50660901_43_dialog_content = "I hope it lets you understand my thoughts a little more clearly...",
  ui_story_5066_50660901_44_dialog_content = "I... look forward to it.",
  ui_story_5066_50660901_45_dialog_content = "Alright, I'm ready...",
  ui_story_5066_50660901_46_dialog_content = "*plays a tune*",
  ui_story_5066_50660901_47_dialog_content = "*plays a tune*",
  ui_story_5066_50660901_48_dialog_content = "*plays a tune*",
  ui_story_5066_50660901_49_dialog_content = "*plays a tune*",
  ui_story_5066_50660901_50_dialog_content = "Ahh... Mama's music always calms me down the most...",
  ui_story_5066_50660901_51_dialog_content = "...",
  ui_story_5066_50660901_52_dialog_content = "Oh... Sorry, I think I... got a little too into it.",
  ui_story_5066_50660901_53_dialog_content = "It's okay... I am deeply moved.",
  ui_story_5066_50660901_54_dialog_content = "I see. You don't view this underwater town as a place to rule but as... your home.",
  ui_story_5066_50660901_55_dialog_content = "Despite facing unfriendliness, you don't harbor resentment because you, who lost your parents, have found a place to belong.",
  ui_story_5066_50660901_56_dialog_content = "You're not fighting for your desires; you're fighting to protect the town that provides you shelter.",
  ui_story_5066_50660901_57_dialog_content = "Oh... It's really nothing that special...",
  ui_story_5066_50660901_58_dialog_content = "I just... I just think that it would be nice if everyone could live happily in a place they can call their own, that's all...",
  ui_story_5066_50660901_59_dialog_content = "Everyone's working hard to build your temple, so... I hope it feels like home for you too!",
  ui_story_5066_50660901_60_dialog_content = "...",
  ui_story_5066_50660901_61_dialog_content = "Perhaps forming a pact with you is the most correct choice made throughout my long years.",
  ui_story_5066_50660901_62_dialog_content = "I'll be waiting with great anticipation for the... home you're going to provide for me.",
  ui_story_5066_50660901_63_dialog_content = "Phew...",
  ui_story_5066_50660901_64_dialog_content = "Helping everyone solve their problems makes me feel happy and all...",
  ui_story_5066_50660901_65_dialog_content = "But I still prefer enjoying my alone time at night.",
  ui_story_5066_50660901_66_dialog_content = "...",
  ui_story_5066_50660901_67_dialog_content = "Huh? It's so late... Who could still be looking for me at this hour...?",
  ui_story_5066_50660901_68_dialog_content = "Hmm... Maybe I should pretend to be asleep...",
  ui_story_5066_50660901_69_dialog_content = "No, I'd feel bad if I did that. I'll just go take a look...",
  ui_story_5066_50660901_70_dialog_content = "<color=#e8d9bb>Wham—</color>",
  ui_story_5066_50660901_71_dialog_content = "H-Hey! No need to be rude... I'm on my way!",
  ui_story_5066_50660901_72_dialog_content = "...",
  ui_story_5066_50660901_73_dialog_content = "Who are you...? And how did you get in here...?",
  ui_story_5066_50660901_74_dialog_content = "Huh?! What's going on...? Why are you... holding my clarinet in your hands?!",
  ui_story_5066_50660901_75_dialog_content = "Tsk, got caught so early...",
  ui_story_5066_50660901_76_dialog_content = "As a dedicated town resident, I'm doing this for your own good, Queen Connolly!",
  ui_story_5066_50660901_77_dialog_content = "You can talk to that monster all because of this thing, huh?",
  ui_story_5066_50660901_78_dialog_content = "It's not just some thing... Th-This is an heirloom from my mama! It's important to me!",
  ui_story_5066_50660901_79_dialog_content = "I don't care if it's some relic or not; if we let you run amok like this, the whole town will pay the price!",
  ui_story_5066_50660901_80_dialog_content = "However, if I present this thing to the Merman King, you and your followers won't be able to cause any troubles. Heh-heh...",
  ui_story_5066_50660901_81_dialog_content = "Brace yourselves for the Merman King's army to crush this foolish town!",
  ui_story_5066_50660901_82_dialog_content = "W-Wait...!",
  ui_story_5066_50660901_83_dialog_content = "Please... Please give it back to me!",
  ui_story_5066_50660901_84_dialog_content = "Tsk, you just won't give up, huh?",
  ui_story_5066_50660901_85_dialog_content = "Hee-hee, I'm already prepared for this!",
  ui_story_5066_50660901_86_dialog_content = "...",
  ui_story_5066_50660901_87_dialog_content = "Eeek!",
  ui_story_5066_50660901_88_dialog_content = "I don't want any trouble, so please... please get out of my way...!",
  ui_story_5066_50660901_89_dialog_content = "...!",
  ui_story_5066_50660901_90_dialog_content = "Ah... I have no choice but to fight, but I swear... I swear I'll catch up to that thief...",
  ui_story_5066_50660902_1_dialog_content = "Huff... Huff... Huff...",
  ui_story_5066_50660902_2_dialog_content = "Even though... I managed to lose those guards...",
  ui_story_5066_50660902_3_dialog_content = "It looks like... the thief... is long gone...",
  ui_story_5066_50660902_4_dialog_content = "Aqua Lord... Are you... still there...?",
  ui_story_5066_50660902_5_dialog_content = "...",
  ui_story_5066_50660902_6_dialog_content = "Boo-hoo... I knew it. Without the clarinet, we can't make contact with each other.",
  ui_story_5066_50660902_7_dialog_content = "<color=#e8d9bb>Boom—!</color>",
  ui_story_5066_50660902_8_dialog_content = "Huh? ... Wh-What was that noise? Don't tell me...",
  ui_story_5066_50660902_9_dialog_content = "Are the king and the thief working together to attack us on every front...?",
  ui_story_5066_50660902_10_dialog_content = "I... I may not be able to reach the Aqua Lord anymore, but...",
  ui_story_5066_50660902_11_dialog_content = "I promised that I wouldn't back down...",
  ui_story_5066_50660902_12_dialog_content = "Your Majesty, this is it!",
  ui_story_5066_50660902_13_dialog_content = "...",
  ui_story_5066_50660902_14_dialog_content = "I never expected a rebellion to break out in such a run-down town.",
  ui_story_5066_50660902_15_dialog_content = "I'll show these rebellious folks just how foolish they are!",
  ui_story_5066_50660902_16_dialog_content = "I now appoint you as vanguards! Follow me, and show them the power and majesty of our Merman Kingdom together!",
  ui_story_5066_50660902_17_dialog_content = "Yes!!!",
  ui_story_5066_50660902_18_dialog_content = "...",
  ui_story_5066_50660902_19_dialog_content = "Is that... the Merman King!?",
  ui_story_5066_50660902_20_dialog_content = "Is he truly here... to seek revenge for his son...?",
  ui_story_5066_50660902_21_dialog_content = "Quick! Go and inform Queen Connolly!",
  ui_story_5066_50660902_22_dialog_content = "Heh, what a bunch of ragtag folks.",
  ui_story_5066_50660902_23_dialog_content = "All you lowly residents, take a good look! I am your king!",
  ui_story_5066_50660902_24_dialog_content = "I now officially proclaim Connolly and her followers as rebels.",
  ui_story_5066_50660902_25_dialog_content = "Here, I seek revenge for the disgrace my son suffered and the rebellion of the town's residents!",
  ui_story_5066_50660902_26_dialog_content = "Guards, prepare for battle!",
  ui_story_5066_50660902_27_dialog_content = "Yes!!!",
  ui_story_5066_50661001_1_dialog_content = "...",
  ui_story_5066_50661001_2_dialog_content = "Merman King... even though you used to oppress us, now, we're not afraid of you anymore!",
  ui_story_5066_50661001_3_dialog_content = "With Queen Connolly's protection, you're no threat to us at all!",
  ui_story_5066_50661001_4_dialog_content = "Hahahaha, Queen Connolly? What a ridiculous name!",
  ui_story_5066_50661001_5_dialog_content = "You might not be afraid of me, but I'm curious to see if you're afraid of this!",
  ui_story_5066_50661001_6_dialog_content = "Is that... a cannon?",
  ui_story_5066_50661001_7_dialog_content = "The barrel is so big... but for Queen Connolly, it's no big deal!",
  ui_story_5066_50661001_8_dialog_content = "Yes, everyone, don't be scared; wait for Queen Connolly to deal with it!",
  ui_story_5066_50661001_9_dialog_content = "Huff... Huff... Huff...",
  ui_story_5066_50661001_10_dialog_content = "Um... Sorry I'm late...",
  ui_story_5066_50661001_11_dialog_content = "Queen Connolly is here!",
  ui_story_5066_50661001_12_dialog_content = "Just like how you sent that annoying prince flying, knock this arrogant king flying as well!",
  ui_story_5066_50661001_13_dialog_content = "Send him flying! Send him flying! Send him flying!",
  ui_story_5066_50661001_14_dialog_content = "Okay...",
  ui_story_5066_50661001_15_dialog_content = "These tentacles are still with me...",
  ui_story_5066_50661001_16_dialog_content = "But...",
  ui_story_5066_50661001_17_dialog_content = "Is this the queen you all were expecting? Quite the sight, I must say!",
  ui_story_5066_50661001_18_dialog_content = "Get ready, vanguards! Fire!",
  ui_story_5066_50661001_19_dialog_content = "<color=#e8d9bb>Boom—!</color>",
  ui_story_5066_50661001_20_dialog_content = "Urgh... I... I'll protect everyone!",
  ui_story_5066_50661001_21_dialog_content = "<color=#e8d9bb>Boom—</color>",
  ui_story_5066_50661001_22_dialog_content = "Ah, not like that... The tentacles are not following my orders...",
  ui_story_5066_50661001_23_dialog_content = "No wait... it's not they don't follow. They just can't understand me...",
  ui_story_5066_50661001_24_dialog_content = "At this rate...",
  ui_story_5066_50661001_25_dialog_content = "<color=#e8d9bb>Boom—!</color>",
  ui_story_5066_50661001_26_dialog_content = "Eh... could it be that Queen Connolly's power can't match the king's cannons and vanguards?",
  ui_story_5066_50661001_27_dialog_content = "She seems a bit off. Are we going to lose...?",
  ui_story_5066_50661001_28_dialog_content = "Stow that kind of talk! There's no way we'll lose!",
  ui_story_5066_50661001_29_dialog_content = "In a situation like this... We should be helping her regain her former strength...",
  ui_story_5066_50661001_30_dialog_content = "That's right, so let's give her all the cover she needs!",
  ui_story_5066_50661001_31_dialog_content = "Everyone... But I...",
  ui_story_5066_50661001_32_dialog_content = "Without my clarinet... I'm nowhere near as strong as I used to be...",
  ui_story_5066_50661001_33_dialog_content = "But these tentacles... A-As long as they're still around, I'll keep fighting...!",
  ui_story_5066_50661102_1_dialog_content = "<color=#e8d9bb>Boom—!</color>",
  ui_story_5066_50661102_2_dialog_content = "Urgh...",
  ui_story_5066_50661102_3_dialog_content = "Connolly! Are you okay?!",
  ui_story_5066_50661102_4_dialog_content = "I... I'm fine, it's just...",
  ui_story_5066_50661102_5_dialog_content = "The Aqua Lord... I don't think it can hold on much longer...",
  ui_story_5066_50661102_6_dialog_content = "<anim type=Shake>éµè Œâ...</anim>",
  ui_story_5066_50661102_7_dialog_content = "<anim type=Shake>ç·tu€¦... ï|'H>■</anim>",
  ui_story_5066_50661102_8_dialog_content = "I'm so sorry... But right now... I can't understand a word you're saying...",
  ui_story_5066_50661102_9_dialog_content = "<anim type=Shake>ç·tuوˆگم€... â€¦â€■</anim>",
  ui_story_5066_50661102_10_dialog_content = "Hey... look at Queen Connolly! She...",
  ui_story_5066_50661102_11_dialog_content = "Those tentacles... They're fading, vanishing...",
  ui_story_5066_50661102_12_dialog_content = "<size=45>Hahahahaha!</size>",
  ui_story_5066_50661102_13_dialog_content = "The so-called new queen of yours is nothing but a figurehead!",
  ui_story_5066_50661102_14_dialog_content = "Everyone, charge! Whoever can catch her will be richly rewarded!",
  ui_story_5066_50661102_15_dialog_content = "Hold it right there! Your opponent's over here!",
  ui_story_5066_50661102_16_dialog_content = "We won't... Let you go anywhere near Connolly...",
  ui_story_5066_50661102_17_dialog_content = "Ridiculous! You believe you can stop me?",
  ui_story_5066_50661102_18_dialog_content = "<color=#e8d9bb>Boom—!</color>",
  ui_story_5066_50661102_19_dialog_content = "Argh! Out of my way, you dirty lapdogs!",
  ui_story_5066_50661102_20_dialog_content = "Leave these guys to me, Dayna. Hurry up and get to Connolly...",
  ui_story_5066_50661102_21_dialog_content = "Got it!",
  ui_story_5066_50661102_22_dialog_content = "<color=#e8d9bb>Boom—!</color>",
  ui_story_5066_50661102_23_dialog_content = "<size=33>Boo-hoo... No, I screwed up again... I'm... I'm so sorry!</size>",
  ui_story_5066_50661102_24_dialog_content = "Hang in there, Connolly!",
  ui_story_5066_50661102_25_dialog_content = "Is... Is that you, Dayna?",
  ui_story_5066_50661102_26_dialog_content = "Yep! Don't worry, I'll cover your escape.",
  ui_story_5066_50661102_27_dialog_content = "Huh...? But I can't just leave everyone behind like this...",
  ui_story_5066_50661102_28_dialog_content = "It's fine, so just leave this to us for now.",
  ui_story_5066_50661102_29_dialog_content = "It's true that we don't really know how to help you right now.",
  ui_story_5066_50661102_30_dialog_content = "But you'll come back once you've regained your strength, right?",
  ui_story_5066_50661102_31_dialog_content = "I...",
  ui_story_5066_50661102_32_dialog_content = "We'll talk later, now go!",
  ui_story_5066_50661102_33_dialog_content = "Boo-hoo... I'll do as you say.",
  ui_story_5066_50661102_34_dialog_content = "<size=33><color=#e8d9bb>Boom—!</color></size>",
  ui_story_5066_50661102_35_dialog_content = "They're still fighting...",
  ui_story_5066_50661102_36_dialog_content = "It's all so scary... Sniff... I really am better off in a dark place like this.",
  ui_story_5066_50661102_37_dialog_content = "As long as I hide in this dark, empty trench, everything will be okay...",
  ui_story_5066_50661102_38_dialog_content = "Everything will be okay... Right?",
  ui_story_5066_50661102_39_dialog_content = "I can finally... Get some decent sleep... Right?",
  ui_story_5066_50661201_1_dialog_content = "<size=45><color=#e8d9bb>Boom—!</color></size>",
  ui_story_5066_50661201_2_dialog_content = "Boo-hoo...",
  ui_story_5066_50661201_3_dialog_content = "I... I should be helping the others...",
  ui_story_5066_50661201_4_dialog_content = "But my body... It won't stop trembling...",
  ui_story_5066_50661201_5_dialog_content = "After all, I can't control these tentacles... Not how I am right now...",
  ui_story_5066_50661201_6_dialog_content = "Even if I went back, I'd just get in everyone's way...",
  ui_story_5066_50661201_7_dialog_content = "<color=#e8d9bb>Whoosh...</color>",
  ui_story_5066_50661201_8_dialog_content = "Wow... So warm... Is this a warm-water current?",
  ui_story_5066_50661201_9_dialog_content = "<color=#e8d9bb>Pat—</color>",
  ui_story_5066_50661201_10_dialog_content = "Hmm? My shoulder...?",
  ui_story_5066_50661201_11_dialog_content = "Eeek! D-Did someone find me...? But whoever it is, they don't seem hostile...",
  ui_story_5066_50661201_12_dialog_content = "Who... Who could have found me here and now of all places...?",
  ui_story_5066_50661201_13_dialog_content = "Hello, Connolly.",
  ui_story_5066_50661201_14_dialog_content = "Wow... What a pretty white dolphin! And its eyes... They're so warm and bright...",
  ui_story_5066_50661201_15_dialog_content = "Who... are you?",
  ui_story_5066_50661201_16_dialog_content = "No need to fear, Connolly. I'm one of the undersea folks you and the Aqua Lord helped.",
  ui_story_5066_50661201_17_dialog_content = "Oh... Really? But I don't seem to recall...",
  ui_story_5066_50661201_18_dialog_content = "I understand. With so many you've helped, it's impossible to remember them all.",
  ui_story_5066_50661201_19_dialog_content = "I know... but still...",
  ui_story_5066_50661201_20_dialog_content = "<size=33>I don't think I could forget such a kind and pretty white dolphin so easily...</size>",
  ui_story_5066_50661201_21_dialog_content = "But it appears you've run into a bit of trouble now.",
  ui_story_5066_50661201_22_dialog_content = "And it's my turn to help you as much as I can.",
  ui_story_5066_50661201_23_dialog_content = "I... boo-hoo... You're absolutely right...",
  ui_story_5066_50661201_24_dialog_content = "But how could I... possibly trouble you with my problems?",
  ui_story_5066_50661201_25_dialog_content = "Why would it be a bother? Inspired by you and how you take pleasure in helping others, I've now mustered the courage to lend a hand.",
  ui_story_5066_50661201_26_dialog_content = "Besides, the underwater world is our shared home, so I'd like to do my part in protecting it.",
  ui_story_5066_50661201_27_dialog_content = "Oh... Is that so...?",
  ui_story_5066_50661201_28_dialog_content = "Well, first, we need to get out of here.",
  ui_story_5066_50661201_29_dialog_content = "This place isn't suitable for you in your current state.",
  ui_story_5066_50661201_30_dialog_content = "I... I know, but where am I supposed to go now?",
  ui_story_5066_50661201_31_dialog_content = "I know of a safe refuge. Would you like to come with me?",
  ui_story_5066_50661201_32_dialog_content = "Yes... If you wouldn't mind...",
  ui_story_5066_50661201_33_dialog_content = "Please... take me with you...",
  ui_story_5066_50661201_34_dialog_content = "... Wait.",
  ui_story_5066_50661201_35_dialog_content = "What's wrong?",
  ui_story_5066_50661201_36_dialog_content = "Will there be other people there too...?",
  ui_story_5066_50661201_37_dialog_content = "Yes, of course. After all, everyone is quite fond of that place.",
  ui_story_5066_50661201_38_dialog_content = "Oh...",
  ui_story_5066_50661201_39_dialog_content = "Dayna and the others are still fighting...",
  ui_story_5066_50661201_40_dialog_content = "But I... I don't know how I'm supposed to help them...",
  ui_story_5066_50661201_41_dialog_content = "Won't the people there... resent me for that?",
  ui_story_5066_50661201_42_dialog_content = "No need to be overly concerned.",
  ui_story_5066_50661201_43_dialog_content = "Maybe you can feel more confident about the reputation you built while helping the residents in the past.",
  ui_story_5066_50661201_44_dialog_content = "More... confident?",
  ui_story_5066_50661201_45_dialog_content = "But I'm no longer the queen they trusted... I'm just a disgraceful runaway now...",
  ui_story_5066_50661201_46_dialog_content = "It's not too late yet.",
  ui_story_5066_50661201_47_dialog_content = "You're simply taking a step back for now, and everyone totally relates to it.",
  ui_story_5066_50661201_48_dialog_content = "Weren't you always helping them in the past, treating the matters of the underwater residents as your own?",
  ui_story_5066_50661201_49_dialog_content = "It's now your turn to seek their help.",
  ui_story_5066_50661201_50_dialog_content = "Am I... really worthy of doing that?",
  ui_story_5066_50661201_51_dialog_content = "Of course, it's because of your kindness that Dayna, Robyn, and everyone else gather around you.",
  ui_story_5066_50661201_52_dialog_content = "Their wisdom will surely be of help in resolving your issues.",
  ui_story_5066_50661201_53_dialog_content = "Everyone's combined knowledge... it really does seem that way...",
  ui_story_5066_50661201_54_dialog_content = "Even if I don't know what to do, maybe one of them... will have the answer?",
  ui_story_5066_50661201_55_dialog_content = "Have faith in everyone, and in yourself.",
  ui_story_5066_50661201_56_dialog_content = "Everything you've done before this won't be in vain.",
  ui_story_5066_50661201_57_dialog_content = "Don't forget, you still have to fulfill the ancient monster's wish, right?",
  ui_story_5066_50661201_58_dialog_content = "Ah!",
  ui_story_5066_50661201_59_dialog_content = "That's right... Aqua Lord... I'm so sorry for embarrassing you like this...",
  ui_story_5066_50661201_60_dialog_content = "But now I know... I need to go ask for everyone's insight!",
  ui_story_5066_50661301_1_dialog_content = "<color=#e8d9bb>Jingle, jingle, jingle—</color>",
  ui_story_5066_50661301_2_dialog_content = "Wow... I had no idea a place like this existed down here...",
  ui_story_5066_50661301_3_dialog_content = "It's so warm and tranquil... It feels like home.",
  ui_story_5066_50661301_4_dialog_content = "This place is rather lovely, isn't it?",
  ui_story_5066_50661301_5_dialog_content = "It is. Thank you so much for bringing me here...",
  ui_story_5066_50661301_6_dialog_content = "Oh... Oh no! I almost wanted to stay here and avoid my troubles...",
  ui_story_5066_50661301_7_dialog_content = "Even though it's so pleasant... I know I can't hide here forever.",
  ui_story_5066_50661301_8_dialog_content = "So, have you figured out what problem you want to ask everyone for help with?",
  ui_story_5066_50661301_9_dialog_content = "Ah... I just noticed... there are actually so many people here...",
  ui_story_5066_50661301_10_dialog_content = "Hey, isn't this Connolly?",
  ui_story_5066_50661301_11_dialog_content = "We got our family's coral reef back from the Mermen, all thanks to you!",
  ui_story_5066_50661301_12_dialog_content = "Our children absolutely adore you! When is it convenient for you to give them another music lesson?",
  ui_story_5066_50661301_13_dialog_content = "Is this... really how everyone sees me...?",
  ui_story_5066_50661301_14_dialog_content = "Indeed, kindness draws folks together.",
  ui_story_5066_50661301_15_dialog_content = "So that's why I should... trust in everyone's good intentions too...",
  ui_story_5066_50661301_16_dialog_content = "I... I understand now!",
  ui_story_5066_50661301_17_dialog_content = "Um... Could I trouble you all for just a few minutes of your time?",
  ui_story_5066_50661301_18_dialog_content = "Go ahead. We can tell that you seem to have encountered some issues.",
  ui_story_5066_50661301_19_dialog_content = "If there's anything we can help with, don't hesitate to tell us!",
  ui_story_5066_50661301_20_dialog_content = "And if there's more...",
  ui_story_5066_50661301_21_dialog_content = "Boo-hoo, I didn't realize everyone would be so willing to help...",
  ui_story_5066_50661301_22_dialog_content = "Ahem. Well, folks, I really appreciate your enthusiasm.",
  ui_story_5066_50661301_23_dialog_content = "But please, one at a time, or else Connolly won't be able to hear anyone.",
  ui_story_5066_50661301_24_dialog_content = "Oh... Thank you, White Dolphin.",
  ui_story_5066_50661301_25_dialog_content = "<size=33>Without you... I don't know what I would do...</size>",
  ui_story_5066_50661301_26_dialog_content = "I... Um, I would like to ask for everyone's insight on a certain matter...",
  ui_story_5066_50661301_27_dialog_content = "Some time ago... A wicked thief stole my clarinet, and so I lost my ability to commune with the Aqua Lord...",
  ui_story_5066_50661301_28_dialog_content = "Does anyone have any ideas... on how I can re-establish my link with the Aqua Lord?",
  ui_story_5066_50661301_29_dialog_content = "...",
  ui_story_5066_50661301_30_dialog_content = "I-I've got a suggestion!",
  ui_story_5066_50661301_31_dialog_content = "Please, go ahead.",
  ui_story_5066_50661301_32_dialog_content = "In the legendary stories I heard when I was young, the Aqua Lord's power is closely tied to the temple!",
  ui_story_5066_50661301_33_dialog_content = "This has to be a crucial clue! Besides, Connolly, didn't you mention the temple earlier?",
  ui_story_5066_50661301_34_dialog_content = "If you can find this ancient temple, you'll regain your power for sure!",
  ui_story_5066_50661301_35_dialog_content = "Connolly, what's your take on this?",
  ui_story_5066_50661301_36_dialog_content = "I think... You make a good point...",
  ui_story_5066_50661301_37_dialog_content = "But I might return too late if I go searching for its ancient temple right now. Also...",
  ui_story_5066_50661301_38_dialog_content = "The Aqua Lord entrusted me with constructing a new temple, but after we worked so hard to build it... The Merman King captured it for himself.",
  ui_story_5066_50661301_39_dialog_content = "Sniff... It's all my fault...",
  ui_story_5066_50661301_40_dialog_content = "Stay hopeful, Connolly. See? The residents already have a new idea!",
  ui_story_5066_50661301_41_dialog_content = "Huh...? Okay then... Please share your thoughts with me!",
  ui_story_5066_50661301_42_dialog_content = "I believe that the clarinet is just one type of musical instrument.",
  ui_story_5066_50661301_43_dialog_content = "Since there's no clarinet, can we use other instruments instead?",
  ui_story_5066_50661301_44_dialog_content = "Maybe the Aqua Lord won't be too picky about the timbre, you know?",
  ui_story_5066_50661301_45_dialog_content = "Not... Picky?",
  ui_story_5066_50661301_46_dialog_content = "Anything come to mind?",
  ui_story_5066_50661301_47_dialog_content = "But... All this time, I believed that its power resided within the instrument my mother left me...",
  ui_story_5066_50661301_48_dialog_content = "Is it really possible to commune with the Aqua Lord without her clarinet...?",
  ui_story_5066_50661301_49_dialog_content = "I believe it's possible.",
  ui_story_5066_50661301_50_dialog_content = "Huh...?!",
  ui_story_5066_50661301_51_dialog_content = "I think that the ability to communicate with the Aqua Lord might be an innate power of your own.",
  ui_story_5066_50661301_52_dialog_content = "My own power...? But... But how could that be...?",
  ui_story_5066_50661301_53_dialog_content = "But think about it: before making the pact, didn't you already have the ability to communicate with the Aqua Lord through music?",
  ui_story_5066_50661301_54_dialog_content = "Besides, even without the clarinet, those tentacles haven't vanished; they're just less responsive.",
  ui_story_5066_50661301_55_dialog_content = "So it might not be about the clarinet alone; what truly matters could be your music, right?",
  ui_story_5066_50661301_56_dialog_content = "My... music?",
  ui_story_5066_50661301_57_dialog_content = "That's right. Try to reflect on your past battles.",
  ui_story_5066_50661301_58_dialog_content = "And think about what exactly gave you the strength...",
  ui_story_5066_50661302_1_dialog_content = "*plays a tune*",
  ui_story_5066_50661302_2_dialog_content = "<color=#e8d9bb>Smack—Smack!</color>",
  ui_story_5066_50661302_3_dialog_content = "...",
  ui_story_5066_50661302_4_dialog_content = "*plays a tune*",
  ui_story_5066_50661302_5_dialog_content = "<color=#e8d9bb>Smack—Smack!</color>",
  ui_story_5066_50661302_6_dialog_content = "Eek...!",
  ui_story_5066_50661302_7_dialog_content = "...",
  ui_story_5066_50661302_8_dialog_content = "I... I remember now...",
  ui_story_5066_50661302_9_dialog_content = "My mother once said that the power of music isn't in the instruments, but in the music itself...",
  ui_story_5066_50661302_10_dialog_content = "I was so busy cherishing the clarinet she left me that I forgot all about what she taught me...",
  ui_story_5066_50661302_11_dialog_content = "But you've remembered it now, haven't you?",
  ui_story_5066_50661302_12_dialog_content = "Yes. So now... If I can find the right piece of music, I might be able to summon the Aqua Lord again...",
  ui_story_5066_50661302_13_dialog_content = "Just like... when I first summoned it in the attic.",
  ui_story_5066_50661302_14_dialog_content = "Do you still remember the musical score you played back then?",
  ui_story_5066_50661302_15_dialog_content = "I do... It's called \"The Shape of Water\"...",
  ui_story_5066_50661302_16_dialog_content = "But...",
  ui_story_5066_50661302_17_dialog_content = "What, you can't play that sheet music anymore?",
  ui_story_5066_50661302_18_dialog_content = "Yes... the music score is still in my aunt's attic...",
  ui_story_5066_50661302_19_dialog_content = "But right now... The entire town is under the Merman King's control.",
  ui_story_5066_50661302_20_dialog_content = "I've only played it a few times, and this piece of music is really complex...",
  ui_story_5066_50661302_21_dialog_content = "Which most likely means... I won't be able to summon the Aqua Lord...",
  ui_story_5066_50661302_22_dialog_content = "Don't stress too much. We still have a lot of options.",
  ui_story_5066_50661302_23_dialog_content = "You can also think about whether there's a composition that could pique the Aqua Lord's interest perhaps?",
  ui_story_5066_50661302_24_dialog_content = "Ah... There is! It's a song called <color=#FFB400>Home</color>!",
  ui_story_5066_50661302_25_dialog_content = "Home?",
  ui_story_5066_50661302_26_dialog_content = "Yes! It's a wonderful song... One that my mother taught me.",
  ui_story_5066_50661302_27_dialog_content = "It's also the song I played... When the Aqua Lord and I finally started to understand one another!",
  ui_story_5066_50661302_28_dialog_content = "I think this is it! This song gotta work!",
  ui_story_5066_50661302_29_dialog_content = "Hmm... I think so, but...",
  ui_story_5066_50661302_30_dialog_content = "I-I can't make any promises, so... could you please accompany me to the temple... and help me summon the Aqua Lord?",
  ui_story_5066_50661302_31_dialog_content = "Rest assured, I'll be right by your side.",
  ui_story_5066_50661302_32_dialog_content = "Plus, everyone over there is still waiting for you.",
  ui_story_5066_50661302_33_dialog_content = "Wait for me, everyone...",
  ui_story_5066_50661302_34_dialog_content = "This is for all of you...",
  ui_story_5066_50661302_35_dialog_content = "If I don't have my clarinet, I'll just use another instrument. If I can't play The Shape of Water, then I'll find another song to play. No matter what... I'll definitely...",
  ui_story_5066_50661302_36_dialog_content = "I'll definitely commune with the Aqua Lord again!",
  ui_story_5066_50661401_1_dialog_content = "Huff... Huff... We're finally getting close...",
  ui_story_5066_50661401_2_dialog_content = "Thank you for staying with me all this time, White Dolphin... If it wasn't for you...",
  ui_story_5066_50661401_3_dialog_content = "These are all your own powers; my part is quite insignificant.",
  ui_story_5066_50661401_4_dialog_content = "And the moment that needs you to show your true powers is yet to come.",
  ui_story_5066_50661401_5_dialog_content = "Oh... B-But you'll always be there to help me, right?",
  ui_story_5066_50661401_6_dialog_content = "Of course, I'll be with you every step of the way.",
  ui_story_5066_50661401_7_dialog_content = "Yo, let's see who this disheveled little girl is?",
  ui_story_5066_50661401_8_dialog_content = "Huh...? Aren't you...?",
  ui_story_5066_50661401_9_dialog_content = "Oh my, isn't this Queen Connolly? Haven't seen you in a while, and you've become such a mess already?",
  ui_story_5066_50661401_10_dialog_content = "Cousin...?",
  ui_story_5066_50661401_11_dialog_content = "What are you doing here?",
  ui_story_5066_50661401_12_dialog_content = "Magnificent debut, isn't it? Jealous, aren't you? This was a gift from the Merman King himself!",
  ui_story_5066_50661401_13_dialog_content = "After all, I was the biggest hero of this battle; now I'm quite the big deal in front of the Merman King!",
  ui_story_5066_50661401_14_dialog_content = "And you, my poor and useless cousin... if only you had listened to me back then and became the Merman Prince's collectible.",
  ui_story_5066_50661401_15_dialog_content = "You'd never end up in such a miserable situation! Hahaha...",
  ui_story_5066_50661401_16_dialog_content = "Greatest contributor...?",
  ui_story_5066_50661401_17_dialog_content = "(But... My cousin's never had any real talent to speak of! How could he be the \"greatest contributor\" in the king's campaign...?)",
  ui_story_5066_50661401_18_dialog_content = "(Could it be?!)",
  ui_story_5066_50661401_19_dialog_content = "It was you... You were the one who stole my clarinet, weren't you?!",
  ui_story_5066_50661401_20_dialog_content = "Oh... So you only realized it now? Isn't that a bit too late and too dumb, my dear cousin?",
  ui_story_5066_50661401_21_dialog_content = "But even if you've realized it, what can you do now?",
  ui_story_5066_50661401_22_dialog_content = "Do you have any way to get back at me? I doubt it!",
  ui_story_5066_50661401_23_dialog_content = "Please... Give it back to me...",
  ui_story_5066_50661401_24_dialog_content = "What did you say? You...",
  ui_story_5066_50661401_25_dialog_content = "I said please give me back my clarinet...!",
  ui_story_5066_50661401_26_dialog_content = "Just empty words...",
  ui_story_5066_50661401_27_dialog_content = "I'm well aware, without that clarinet, you're absolutely worthless!",
  ui_story_5066_50661401_28_dialog_content = "Me...? It's true that there's nothing special about me...",
  ui_story_5066_50661401_29_dialog_content = "But true power... lies in music!",
  ui_story_5066_50661401_30_dialog_content = "Power... What a joke...",
  ui_story_5066_50661401_31_dialog_content = "Even without my clarinet, I can use my voice...",
  ui_story_5066_50661401_32_dialog_content = "And even without my musical scores... Their melodies and emotions were etched into my heart long ago.",
  ui_story_5066_50661401_33_dialog_content = "Right now, all I need to do is sing!",
  ui_story_5066_50661401_34_dialog_content = "*sings*",
  ui_story_5066_50661401_35_dialog_content = "<color=#e8d9bb>Like a princess returning to her castle, Connolly sings as she ascends the winding stairs, using her voice to summon the Aqua Lord...</color>",
  ui_story_5066_50661401_36_dialog_content = "<color=#e8d9bb>At the same time, she finally voices the feelings she kept buried in her heart for so long.</color>",
  ui_story_5066_50661401_37_dialog_content = "Shut up! Stop singing... Stop! Stay away from me!",
  ui_story_5066_50661401_38_dialog_content = "Only a place where all come together can be called home!♪",
  ui_story_5066_50661401_39_dialog_content = "An empty castle, no matter how grand, will always feel alone!♪",
  ui_story_5066_50661401_40_dialog_content = "So please hear my call and return to my side!♪",
  ui_story_5066_50661401_41_dialog_content = "For here is your home, where you have no need to hide!♪",
  ui_story_5066_50661401_42_dialog_content = "<color=#e8d9bb>As her voice rings out, various fish and Lumina particles begin to gather around Connolly, as if joining her in praying for a miracle...</color>",
  ui_story_5066_50661401_43_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5066_50661401_44_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5066_50661401_45_dialog_content = "...",
  ui_story_5066_50661401_46_dialog_content = "Aqua Lord... I'm so glad to see you again...",
  ui_story_5066_50661401_47_dialog_content = "...",
  ui_story_5066_50661401_48_dialog_content = "I'm so sorry... I ruined everything...",
  ui_story_5066_50661401_49_dialog_content = "You must be so disappointed... to have made a pact with someone as shameful and useless as me... right?",
  ui_story_5066_50661401_50_dialog_content = "Maybe I don't have the right to say we're bonded anymore... And maybe it's shameless of me to ask... But I'm going to do it anyways!",
  ui_story_5066_50661401_51_dialog_content = "Right now... I really, really need your help!",
  ui_story_5066_50661401_52_dialog_content = "So can you please... lend me your power one more time?!",
  ui_story_5066_50661401_53_dialog_content = "...",
  ui_story_5066_50661401_54_dialog_content = "I don't loathe your current attitude.",
  ui_story_5066_50661401_55_dialog_content = "These accidents are not all your fault.",
  ui_story_5066_50661401_56_dialog_content = "At least your intentions have reached me.",
  ui_story_5066_50661401_57_dialog_content = "Then does that mean...?!",
  ui_story_5066_50661401_58_dialog_content = "But now... I can't help you...",
  ui_story_5066_50661401_59_dialog_content = "Oh... I knew it... but I understand...",
  ui_story_5066_50661401_60_dialog_content = "Do not get me wrong.",
  ui_story_5066_50661401_61_dialog_content = "The medium was lost, and the pact was broken prematurely. I've lost my physical form in this world.",
  ui_story_5066_50661401_62_dialog_content = "Now, if you wish to gain my power, you must go to the temple...",
  ui_story_5066_50661401_63_dialog_content = "Well, to be precise, you must go to that extravagant castle you've built for me and extract all the remaining power.",
  ui_story_5066_50661401_64_dialog_content = "But...",
  ui_story_5066_50661401_65_dialog_content = "Um... Is there some sort of catch...?",
  ui_story_5066_50661401_66_dialog_content = "But if you want to make the most of that power, you'll need to inherit the temple and become the true Aqua Queen.",
  ui_story_5066_50661401_67_dialog_content = "The true... Aqua Queen...?",
  ui_story_5066_50661401_68_dialog_content = "Are you saying... That I'm just an imposter right now?",
  ui_story_5066_50661401_69_dialog_content = "You're not an imposter. The thing is, if you only aim to protect yourself, you've come far enough.",
  ui_story_5066_50661401_70_dialog_content = "My residual presence is enough to shelter you.",
  ui_story_5066_50661401_71_dialog_content = "However, if you aim to protect the town, my residual presence falls far short in power.",
  ui_story_5066_50661401_72_dialog_content = "You'll need to embrace more power and... bear more responsibility.",
  ui_story_5066_50661401_73_dialog_content = "You shall step up, from the shadows to the spotlight, into the darkness where even my power can't shield you...",
  ui_story_5066_50661401_74_dialog_content = "Ehehehe...",
  ui_story_5066_50661401_75_dialog_content = "What? Do you find my words amusing?",
  ui_story_5066_50661401_76_dialog_content = "It's just that for the very first time... You seem kind of dense...",
  ui_story_5066_50661401_77_dialog_content = "Why do you say that...?",
  ui_story_5066_50661401_78_dialog_content = "Weren't my feelings perfectly clear in my song just now? Also...",
  ui_story_5066_50661401_79_dialog_content = "Now that the White Dolphin is helping me, along with everyone else...",
  ui_story_5066_50661401_80_dialog_content = "Of course I would choose to keep going.",
  ui_story_5066_50661401_81_dialog_content = "It seems I may have underestimated you this time...",
  ui_story_5066_50661401_82_dialog_content = "Then, show me the power of your determination.",
  ui_story_5066_50661401_83_dialog_content = "I will... And I promise I won't disappoint you again...",
  ui_story_5066_50661401_84_dialog_content = "Now, dear cousin... Will you please give me back my clarinet?",
  ui_story_5066_50661401_85_dialog_content = "Or... would you rather feel the full force of my anger for what you've done...?",
  ui_story_5066_50661401_86_dialog_content = "Tsk...",
  ui_story_5066_50661401_87_dialog_content = "(Her power hasn't fully recovered. As long as I can stop her here, she'll stay an ordinary girl!)",
  ui_story_5066_50661401_88_dialog_content = "Heh, come on, cousin...",
  ui_story_5066_50661401_89_dialog_content = "Serving the Fishman King, my strength has been boosted far more than you can ever imagine.",
  ui_story_5066_50661401_90_dialog_content = "And this time, I'm going all out, the kind of all-out that'll end your miserable life! Bring it on!",
  ui_story_5066_50661402_1_dialog_content = "<color=#e8d9bb>Smack—Smack!</color>",
  ui_story_5066_50661402_2_dialog_content = "*sings*",
  ui_story_5066_50661402_3_dialog_content = "Aghhh! Ouch ouch... That's enough! Connolly, stop it. I'm your cousin!",
  ui_story_5066_50661402_4_dialog_content = "The clarinet, you say? Alright, I... I'll give it back to you...",
  ui_story_5066_50661402_5_dialog_content = "Please... please don't kill me! I beg of you...",
  ui_story_5066_50661402_6_dialog_content = "You wouldn't do something so cruel and unjust, would you? Your aunt and uncle would be devastated, you know, devastated!",
  ui_story_5066_50661402_7_dialog_content = "That's right, they're still expecting you to return home!",
  ui_story_5066_50661402_8_dialog_content = "Home...",
  ui_story_5066_50661402_9_dialog_content = "Exactly, home, the home of us! Come on, let's go home to be with your families, the ones who really love you!",
  ui_story_5066_50661402_10_dialog_content = "...",
  ui_story_5066_50661402_11_dialog_content = "Although I'm thankful to my aunt and uncle for taking me in after I lost everything...",
  ui_story_5066_50661402_12_dialog_content = "That place isn't my home anymore...",
  ui_story_5066_50661402_13_dialog_content = "Besides, you were the one who wanted to take me away from their home... Weren't you, cousin?!",
  ui_story_5066_50661402_14_dialog_content = "And now you want to destroy these people's homes too... Make no mistake, you're my enemy now.",
  ui_story_5066_50661402_15_dialog_content = "Eek! No... it's just a big misunderstanding, you... please don't kill me!!",
  ui_story_5066_50661402_16_dialog_content = "I... I'd never kill anyone... You and I are not the same...",
  ui_story_5066_50661402_17_dialog_content = "So leave... leave this town right now... And never come back!",
  ui_story_5066_50661402_18_dialog_content = "Alright, I understand. Just let me go; I'll never come back, and you'll never see me again...",
  ui_story_5066_50661402_19_dialog_content = "...",
  ui_story_5066_50661402_20_dialog_content = "I shouldn't be bothering with my cousin right now...",
  ui_story_5066_50661402_21_dialog_content = "The Merman King has already occupied most of this area. Not only that...",
  ui_story_5066_50661402_22_dialog_content = "<color=#e8d9bb>Boom—!</color>",
  ui_story_5066_50661402_23_dialog_content = "The sound of cannon fire is getting closer. In fact, it sounds like it's coming straight towards me...",
  ui_story_5066_50661402_24_dialog_content = "But I'm ready for it this time!",
  ui_story_5066_50661402_25_dialog_content = "Dayna, Robyn, everyone... Please be safe!",
  ui_story_5066_50661501_1_dialog_content = "<color=#e8d9bb>Boom—!</color>",
  ui_story_5066_50661501_2_dialog_content = "Argh! Don't tell me we have to give up this position too?!",
  ui_story_5066_50661501_3_dialog_content = "There's no end to all these stinkin' Merman guards!",
  ui_story_5066_50661501_4_dialog_content = "Dayna... We should retreat for now...",
  ui_story_5066_50661501_5_dialog_content = "But if we retreat now, it'll only put Connolly in more danger!",
  ui_story_5066_50661501_6_dialog_content = "You can keep going, can't you Robyn?",
  ui_story_5066_50661501_7_dialog_content = "If it's for Connolly... I can hold on a little longer.",
  ui_story_5066_50661501_8_dialog_content = "<color=#e8d9bb>Smack—Smack!</color>",
  ui_story_5066_50661501_9_dialog_content = "Were those... tentacles?!",
  ui_story_5066_50661501_10_dialog_content = "It's Connolly... she's back...",
  ui_story_5066_50661501_11_dialog_content = "Uh... I-I'm sorry for keeping everyone waiting...!",
  ui_story_5066_50661501_12_dialog_content = "\"Keep us waiting\"? Quit being so polite with us already!",
  ui_story_5066_50661501_13_dialog_content = "Seeing that you're okay... is the best news we could receive...",
  ui_story_5066_50661501_14_dialog_content = "So did you get your powers back?",
  ui_story_5066_50661501_15_dialog_content = "No, it seems like... She's gotten even stronger...",
  ui_story_5066_50661501_16_dialog_content = "Perfect! Then let's mop the floor with these jerks and send them running, Connolly!",
  ui_story_5066_50661501_17_dialog_content = "G-Got it! I'll give it my all!",
  ui_story_5066_50661501_18_dialog_content = "<color=#e8d9bb>Clang—Crack—</color>",
  ui_story_5066_50661501_19_dialog_content = "<color=#e8d9bb>Whoosh, whoosh, whoosh—Smack!</color>",
  ui_story_5066_50661501_20_dialog_content = "Hey now, I thought you guys were supposed to be stronger than this!",
  ui_story_5066_50661501_21_dialog_content = "Can't even a single one of you fight?!",
  ui_story_5066_50661501_22_dialog_content = "<color=#e8d9bb>Clang—Crack—</color>",
  ui_story_5066_50661501_23_dialog_content = "Connolly... The strength you have now... I'm so relieved...",
  ui_story_5066_50661501_24_dialog_content = "Yes... And it's all because you guys bought me so much time. Thank you so, so much...",
  ui_story_5066_50661501_25_dialog_content = "No need to thank us, especially when there's plenty of fighting left to do!",
  ui_story_5066_50661501_26_dialog_content = "<color=#e8d9bb>Clang—Crack—</color>",
  ui_story_5066_50661501_27_dialog_content = "...",
  ui_story_5066_50661501_28_dialog_content = "Enough small fries! Bring out that arrogant king of yours already!",
  ui_story_5066_50661501_29_dialog_content = "Robyn, go give Connolly a hand.",
  ui_story_5066_50661501_30_dialog_content = "Roger...",
  ui_story_5066_50661501_31_dialog_content = "Looks like this is the true power of the Aqua Queen.",
  ui_story_5066_50661501_32_dialog_content = "Interesting. It indeed is somewhat incredible.",
  ui_story_5066_50661501_33_dialog_content = "But do you all really believe I'm at the losing end now?",
  ui_story_5066_50661501_34_dialog_content = "You... Whatever it is you're plotting, I... I won't let you get away with it!",
  ui_story_5066_50661501_35_dialog_content = "Hahahaha, stop me? I have all the intel about you!",
  ui_story_5066_50661501_36_dialog_content = "So, the Aqua Lord's power now all comes from that home you've built, that castle, doesn't it?",
  ui_story_5066_50661501_37_dialog_content = "I'll bring more cannonballs from the shallow waters and blow up the castle completely! Let the Aqua Lord's power utterly disperse!",
  ui_story_5066_50661501_38_dialog_content = "And you call yourself a king, fighting like that? You're despicable, but at least you have the nerve to finally say it!",
  ui_story_5066_50661501_39_dialog_content = "Heh, you have a problem with it? What can you do?",
  ui_story_5066_50661501_40_dialog_content = "Connolly, if you declare your allegiance to me now, I might let you and that monster live.",
  ui_story_5066_50661501_41_dialog_content = "Make your choice fast; I don't want to waste more time with you.",
  ui_story_5066_50661501_42_dialog_content = "I... I promised the Aqua Lord that I would protect its home... And everyone else's home too.",
  ui_story_5066_50661501_43_dialog_content = "This is my duty... And I won't run from it anymore!",
  ui_story_5066_50661501_44_dialog_content = "If you're truly willing to blow up the temple...",
  ui_story_5066_50661501_45_dialog_content = "Then by my authority as the Aqua Queen... To defend this town, I hereby declare war on you!",
  ui_story_5066_50661501_46_dialog_content = "Excellent, it's time to put an end to the farce of you rebels.",
  ui_story_5066_50661501_47_dialog_content = "All units! On my command! Launch a full-scale attack on the town!",
  ui_story_5066_50661501_48_dialog_content = "Don't spare any of the rebels in the town!",
  ui_story_5066_50661501_49_dialog_content = "...",
  ui_story_5066_50661501_50_dialog_content = "...",
  ui_story_5066_50661501_51_dialog_content = "...",
  ui_story_5066_50661501_52_dialog_content = "<size=50>Ohhhhhh!</size>",
  ui_story_5066_50661601_1_dialog_content = "*plays a tune*",
  ui_story_5066_50661601_2_dialog_content = "<color=#e8d9bb>Smack—Smack!</color>",
  ui_story_5066_50661601_3_dialog_content = "Urgh...",
  ui_story_5066_50661601_4_dialog_content = "Urgh...",
  ui_story_5066_50661601_5_dialog_content = "...",
  ui_story_5066_50661601_6_dialog_content = "Looks like the intel from that joker was wrong...",
  ui_story_5066_50661601_7_dialog_content = "The power comes from the music itself, not that clarinet!",
  ui_story_5066_50661601_8_dialog_content = "But this way, heh, things just got too easy!",
  ui_story_5066_50661601_9_dialog_content = "On my command!",
  ui_story_5066_50661601_10_dialog_content = "...!",
  ui_story_5066_50661601_11_dialog_content = "Make noise as loud as possible to interfere with the Aqua Queen's music!",
  ui_story_5066_50661601_12_dialog_content = "Yes!",
  ui_story_5066_50661601_13_dialog_content = "Arghhhh! Shut your stupid mouths, all of you!",
  ui_story_5066_50661601_14_dialog_content = "We can't let those jerks keep making all this noise! Let's go, Robyn!",
  ui_story_5066_50661601_15_dialog_content = "Understood... We have to stop them...",
  ui_story_5066_50661601_16_dialog_content = "<color=#e8d9bb>Clang—Wham—</color>",
  ui_story_5066_50661601_17_dialog_content = "Louder, make it louder! Let it resound!",
  ui_story_5066_50661601_18_dialog_content = "Urgh... They're so loud! I can barely hear my own voice...",
  ui_story_5066_50661601_19_dialog_content = "At this rate... Don't tell me it'll happen again...",
  ui_story_5066_50661601_20_dialog_content = "No need to fear, Connolly.",
  ui_story_5066_50661601_21_dialog_content = "The White Dolphin... You came to help me again?",
  ui_story_5066_50661601_22_dialog_content = "I... I know I shouldn't lose heart so easily, but... How am I supposed to play my song now...?",
  ui_story_5066_50661601_23_dialog_content = "Just be yourself.",
  ui_story_5066_50661601_24_dialog_content = "Just... Be myself...?",
  ui_story_5066_50661601_25_dialog_content = "That's right. Your performance isn't meant for battle, is it?",
  ui_story_5066_50661601_26_dialog_content = "What is the purpose of your music?",
  ui_story_5066_50661601_27_dialog_content = "My music's meaning...",
  ui_story_5066_50661601_28_dialog_content = "Still, I'm not completely unhappy...",
  ui_story_5066_50661601_29_dialog_content = "And that's because... I still have my music! I still have the instrument and sheet music my mama left me...",
  ui_story_5066_50661601_30_dialog_content = "<color=#e8d9bb>Whenever Connolly feels lonely, she plays those familiar melodies.</color>",
  ui_story_5066_50661601_31_dialog_content = "<color=#e8d9bb>A joyful march in A Major, a lyrical ballad in B Minor, and a somber sonata in C Major. These songs are not just her friends, but her salvation.</color>",
  ui_story_5066_50661601_32_dialog_content = "I... I understand now.",
  ui_story_5066_50661601_33_dialog_content = "I was always alone when I played my music. It was my way of saving myself...",
  ui_story_5066_50661601_34_dialog_content = "That irreplaceable joy of playing music belongs to me and no one else... It's also what I do best...",
  ui_story_5066_50661601_35_dialog_content = "Which means I can still do it!",
  ui_story_5066_50661601_36_dialog_content = "*plays a tune*",
  ui_story_5066_50661601_37_dialog_content = "Noise, where's the noise you make?! You must be louder than that damn music!",
  ui_story_5066_50661601_38_dialog_content = "*plays a tune*",
  ui_story_5066_50661601_39_dialog_content = "Uh-oh, the Merman King's looking real salty now!",
  ui_story_5066_50661601_40_dialog_content = "Now is the time... To turn the tides of battle...",
  ui_story_5066_50661701_1_dialog_content = "<color=#e8d9bb>Bang—Bang—</color>",
  ui_story_5066_50661701_2_dialog_content = "Come on, you bunch of fish-faced freaks! Gimme a real challenge!",
  ui_story_5066_50661701_3_dialog_content = "Ever since Connolly came back, the battle's gotten a lot easier... What a relief...",
  ui_story_5066_50661701_4_dialog_content = "These useless guards; not dependable in critical moments at all...",
  ui_story_5066_50661701_5_dialog_content = "But you rebels, don't get too smug so early.",
  ui_story_5066_50661701_6_dialog_content = "As a king, I didn't intend to fight in person.",
  ui_story_5066_50661701_7_dialog_content = "But with things like this now...",
  ui_story_5066_50661701_8_dialog_content = "...!?",
  ui_story_5066_50661701_9_dialog_content = "Your Majesty, you don't have to...",
  ui_story_5066_50661701_10_dialog_content = "Shut up! Tell everyone to cease their meaningless attacks and redirect all firepower towards the castle!",
  ui_story_5066_50661701_11_dialog_content = "I'm covering the bombardment personally!",
  ui_story_5066_50661701_12_dialog_content = "We're wiping this town off the map today, starting with that cursed castle!",
  ui_story_5066_50661701_13_dialog_content = "But this way, even if we win this battle, we won't gain anything...",
  ui_story_5066_50661701_14_dialog_content = "Shut up, you useless bunch! Just do as I say!",
  ui_story_5066_50661701_15_dialog_content = "Yes!!!",
  ui_story_5066_50661701_16_dialog_content = "<color=#e8d9bb>Boom—!</color>",
  ui_story_5066_50661701_17_dialog_content = "That cannon blast seemed even more powerful than before!",
  ui_story_5066_50661701_18_dialog_content = "Is he... trying to level the entire town...?",
  ui_story_5066_50661701_19_dialog_content = "<color=#e8d9bb>Boom—!</color>",
  ui_story_5066_50661701_20_dialog_content = "And it looks like they're focusing fire on the temple itself!",
  ui_story_5066_50661701_21_dialog_content = "At this rate... The temple will be reduced to rubble in no time...",
  ui_story_5066_50661701_22_dialog_content = "No... I can't let him destroy the temple!",
  ui_story_5066_50661701_23_dialog_content = "This is... The Aqua Lord's home... And everyone worked so hard to build it!",
  ui_story_5066_50661701_24_dialog_content = "We can't... We won't let the Merman King tear it down!",
  ui_story_5066_50661701_25_dialog_content = "<color=#e8d9bb>Whoosh—Whoosh—Whoosh—</color>",
  ui_story_5066_50661701_26_dialog_content = "<color=#e8d9bb>With all of her strength, Connolly blocks every incoming cannon blast with her tentacles.</color>",
  ui_story_5066_50661701_27_dialog_content = "<color=#e8d9bb>Boom—!</color>",
  ui_story_5066_50661701_28_dialog_content = "Connolly!!!",
  ui_story_5066_50661701_29_dialog_content = "You're gonna get hurt if you keep this up!",
  ui_story_5066_50661701_30_dialog_content = "But the temple... I can't let it...",
  ui_story_5066_50661701_31_dialog_content = "...",
  ui_story_5066_50661701_32_dialog_content = "It's okay, Connolly, it's alright.",
  ui_story_5066_50661701_33_dialog_content = "Huh... Is that you, Aqua Lord...?",
  ui_story_5066_50661701_34_dialog_content = "Your determination and emotions are all clear to me.",
  ui_story_5066_50661701_35_dialog_content = "I will protect the town. So you can go all out against the Merman King.",
  ui_story_5066_50661701_36_dialog_content = "But...",
  ui_story_5066_50661701_37_dialog_content = "There are no \"buts.\" Connolly, I've already told you that being a true queen comes with more responsibilities...",
  ui_story_5066_50661701_38_dialog_content = "But our pact... And your home...",
  ui_story_5066_50661701_39_dialog_content = "Home... Ahahahahahah...",
  ui_story_5066_50661701_40_dialog_content = "This time, it's you who doesn't get it.",
  ui_story_5066_50661701_41_dialog_content = "Me...?",
  ui_story_5066_50661701_42_dialog_content = "You've long told me through your songs the true meaning of home. Don't you remember?",
  ui_story_5066_50661701_43_dialog_content = "The town is the home of all underwater residents, and it's the townsfolks and you together who built me a new home...",
  ui_story_5066_50661701_44_dialog_content = "As long as the town remains, the home I desire can always be reconstructed, sooner or later.",
  ui_story_5066_50661701_45_dialog_content = "Aqua Lord...",
  ui_story_5066_50661701_46_dialog_content = "Go now. This time, Let me join you... to protect our beloved town, our most cherished... home!",
  ui_story_5066_50661702_1_dialog_content = "<color=#e8d9bb>Whoosh—Smack—</color>",
  ui_story_5066_50661702_2_dialog_content = "Ughhh...",
  ui_story_5066_50661702_3_dialog_content = "<color=#e8d9bb>Whoosh—Slap—</color>",
  ui_story_5066_50661702_4_dialog_content = "Haa... Haa... It's finally over...",
  ui_story_5066_50661702_5_dialog_content = "Drat...",
  ui_story_5066_50661702_6_dialog_content = "I... the mighty Merman King... can't believe I... lost to someone like you...",
  ui_story_5066_50661702_7_dialog_content = "Heheheheh... No, I haven't lost yet! This is not over!",
  ui_story_5066_50661702_8_dialog_content = "Connolly, listen!",
  ui_story_5066_50661702_9_dialog_content = "<color=#e8d9bb>Boom—!</color>",
  ui_story_5066_50661702_10_dialog_content = "The bombardment isn't over yet, but you don't have the power to stop it anymore!",
  ui_story_5066_50661702_11_dialog_content = "The victory shall be mine! MINE!",
  ui_story_5066_50661702_12_dialog_content = "Hahahaha... Long live the Merman Kingdom!",
  ui_story_5066_50661702_13_dialog_content = "The town... everyone...",
  ui_story_5066_50661702_14_dialog_content = "I... I may be completely exhausted now, but... I'm not alone in this fight!",
  ui_story_5066_50661702_15_dialog_content = "<color=#e8d9bb>Boom—!</color>",
  ui_story_5066_50661702_16_dialog_content = "Aaahhhh—",
  ui_story_5066_50661702_17_dialog_content = "No matter how loud your big talk is, it won't overshadow the sound of the cannons!",
  ui_story_5066_50661702_18_dialog_content = "I'm the winner! It's my victory!",
  ui_story_5066_50661702_19_dialog_content = "<color=#e8d9bb>Under a barrage of cannon fire, Connolly's body sways helplessly like seaweed.</color>",
  ui_story_5066_50661702_20_dialog_content = "<color=#e8d9bb>Looking up, she sees something floating far away on the surface of the water. A warm and familiar glow...</color>",
  ui_story_5066_50661702_21_dialog_content = "Aqua Lord...",
  ui_story_5066_50661702_22_dialog_content = "I... I defeated the Merman King, just like I said I would... I fulfilled my duties!",
  ui_story_5066_50661702_23_dialog_content = "But your body... What happened to it?!",
  ui_story_5066_50661702_24_dialog_content = "You've done well...",
  ui_story_5066_50661702_25_dialog_content = "But to protect the town... you'll need even more advanced power, the power of the true Aqua Queen...",
  ui_story_5066_50661702_26_dialog_content = "I now... pass on this power to you.",
  ui_story_5066_50661702_27_dialog_content = "No... Wait, Aqua Lord! This isn't what we agreed on...!",
  ui_story_5066_50661702_28_dialog_content = "Aren't we... Aren't we supposed to defend this town together?!",
  ui_story_5066_50661702_29_dialog_content = "Indeed, you... will inherit all of my power...",
  ui_story_5066_50661702_30_dialog_content = "And I'll be with you always, guarding the town...",
  ui_story_5066_50661702_31_dialog_content = "Guarding... our home.",
  ui_story_5066_50661702_32_dialog_content = "Wait, Aqua Lord... please don't disappear... don't leave me all alone...",
  ui_story_5066_50661702_33_dialog_content = "Forever, you... won't be alone...",
  ui_story_5066_50661702_34_dialog_content = "<color=#e8d9bb>Whoosh...</color>",
  ui_story_5066_50661702_35_dialog_content = "Aqua... Lord...",
  ui_story_5066_50661702_36_dialog_content = "This power... it feels so warm...",
  ui_story_5066_50661702_37_dialog_content = "This is... The full power of the Aqua Lord... which it passed on to me...",
  ui_story_5066_50661702_38_dialog_content = "But now isn't the time to mourn...!",
  ui_story_5066_50661702_39_dialog_content = "The Aqua Lord's will and wishes... They're mine now!",
  ui_story_5066_50661702_40_dialog_content = "Hmph... nothing but bluffs!",
  ui_story_5066_50661702_41_dialog_content = "The truth is, that monster couldn't withstand my bombardment... and vanished. Isn't that obvious?",
  ui_story_5066_50661702_42_dialog_content = "The cannon will not stop firing, and you...",
  ui_story_5066_50661702_43_dialog_content = "<color=#e8d9bb>Connolly doesn't speak, but instead softly raises her clarinet.</color>",
  ui_story_5066_50661702_44_dialog_content = "You... already at such a point, what more can you do?!",
  ui_story_5066_50661702_45_dialog_content = "This lullaby is dedicated to you, as well as the rest of your violent, heartless soldiers.",
  ui_story_5066_50661702_46_dialog_content = "Your dream of crushing this town is over. Now it's time... for me to send you off into a new dream.",
  ui_story_5066_50661702_47_dialog_content = "Please enjoy it as we send you back to the Shallows!",
  ui_story_5066_50661702_48_dialog_content = "*plays a tune*",
  ui_story_5066_50661702_49_dialog_content = "<color=#e8d9bb>Connolly plays a tender and moving piece, one that is brimming with the power of friendship, remembrance, and her iron-clad resolve.</color>",
  ui_story_5066_50661702_50_dialog_content = "<color=#e8d9bb>Every enemy, including the Merman King, falls into a deep sleep as Connolly delivers a perfect performance...</color>",
  ui_story_5066_50661702_51_dialog_content = "I can't believe it. A single song is all it took to turn those bloodthirsty mermen into a school of sleepy fish!",
  ui_story_5066_50661702_52_dialog_content = "Get up, bait-breath! We're not done fighting yet!",
  ui_story_5066_50661702_53_dialog_content = "So this is Connolly's power... But it seems like something bad happened as well...",
  ui_story_5066_50661702_54_dialog_content = "Yeah, I know.",
  ui_story_5066_50661702_55_dialog_content = "The Aqua Lord's gone now, right?",
  ui_story_5066_50661702_56_dialog_content = "Which is why we should be comforting her right now instead of standing around here...",
  ui_story_5066_50661702_57_dialog_content = "Gotcha! Let's move out!",
  ui_story_5066_50661702_58_dialog_content = "Is it... Is it really all over this time?",
  ui_story_5066_50661702_59_dialog_content = "You did a fantastic job, Connolly.",
  ui_story_5066_50661702_60_dialog_content = "P-Please don't praise me. I should be thanking you for guiding me all this time...",
  ui_story_5066_50661702_61_dialog_content = "Just a little help from me. I must say, your appearance while performing that lullaby just now was both dashing and graceful.",
  ui_story_5066_50661702_62_dialog_content = "Aaahhhh... Y-You're making fun of me, aren't you?!",
  ui_story_5066_50661702_63_dialog_content = "Okay, your friends are coming over just in time; let's all celebrate this victory together!",
  ui_story_5066_50661702_64_dialog_content = "Hey, Connolly! Over here!",
  ui_story_5066_50661702_65_dialog_content = "Look, we rounded up all the sleeping mermen in one place!",
  ui_story_5066_50661702_66_dialog_content = "They're really slimy... It was a lot more work than I thought...",
  ui_story_5066_50661702_67_dialog_content = "The Merman King's got a pretty big head though. Think we can squeeze him in there?",
  ui_story_5066_50661702_68_dialog_content = "I think... He'll fit just fine!",
  ui_story_5066_50661702_69_dialog_content = "Alright, here goes!",
  ui_story_5066_50661702_70_dialog_content = "Attacking a defenseless town with cannons and explosives... I bet even a tyrant like him never thought...",
  ui_story_5066_50661702_71_dialog_content = "That he'd get shot out of a cannon someday too, huh?",
  ui_story_5066_50661702_72_dialog_content = "I'm honestly excited to see how it goes...",
  ui_story_5066_50661702_73_dialog_content = "I... I just think this is the best way to get them all out of here...",
  ui_story_5066_50661702_74_dialog_content = "This little town will finally know peace and safety after this...",
  ui_story_5066_50661702_75_dialog_content = "Could you light the fuse already, Connolly? I'm dying to see this thing go off!",
  ui_story_5066_50661702_76_dialog_content = "Okay, sure...",
  ui_story_5066_50661702_77_dialog_content = "Three, two, one—Fire!",
  ui_story_5066_50661702_78_dialog_content = "<size=45><color=#e8d9bb>Boom—!</color></size>",
  ui_story_5066_50661702_79_dialog_content = "Um... Is this how everything should end, White Dolphin...?",
  ui_story_5066_50661702_80_dialog_content = "Of course. There's no better ending than this.",
  ui_story_5066_50661702_81_dialog_content = "To you all, ugly Mermen, I hope you enjoy this dream within a dream.",
  ui_story_5066_50661801_1_dialog_content = "Phew... It's finally all over...",
  ui_story_5066_50661801_2_dialog_content = "This whole thing felt like a bizarre dream...",
  ui_story_5066_50661801_3_dialog_content = "Maybe... If I was able to fall asleep like the rest of those fish...",
  ui_story_5066_50661801_4_dialog_content = "Would I... Be able to see the Aqua Lord one more time?",
  ui_story_5066_50661801_5_dialog_content = "Hey Connolly, these people say that their homes were destroyed in the battle. Shouldn't we find a way to shelter them for now?",
  ui_story_5066_50661801_6_dialog_content = "And this child says he got separated from his mother... But don't worry, I'll help him look...",
  ui_story_5066_50661801_7_dialog_content = "Ahh, sorry about that...",
  ui_story_5066_50661801_8_dialog_content = "Now's not the time to wallow in my sadness...",
  ui_story_5066_50661801_9_dialog_content = "I promised that I would become a true Aqua Queen... And I refuse to run from my duties ever again...",
  ui_story_5066_50661801_10_dialog_content = "Dayna! Robyn! I'll be right there...",
  ui_story_5066_50661801_11_dialog_content = "<color=#e8d9bb>Swish—Swish—Swish—</color>",
  ui_story_5066_50661801_12_dialog_content = "Huh?!",
  ui_story_5066_50661801_13_dialog_content = "Are these... water tentacles? But they're so tiny...",
  ui_story_5066_50661801_14_dialog_content = "Aqua Lord... You're still here?! You never left me, did you...?",
  ui_story_5066_50661801_15_dialog_content = "Aqua Lord? But... aren't you the true Aqua Lord?!",
  ui_story_5066_50661801_16_dialog_content = "Huh...? M-Me?!",
  ui_story_5066_50661801_17_dialog_content = "That's right, we are your servants... and your friends...",
  ui_story_5066_50661801_18_dialog_content = "We've come to be with you just so you won't be lonely!",
  ui_story_5066_50661801_19_dialog_content = "Keep me company...?",
  ui_story_5066_50661801_20_dialog_content = "Indeed, you... will inherit all of my power...",
  ui_story_5066_50661801_21_dialog_content = "And I'll be with you always, guarding the town...",
  ui_story_5066_50661801_22_dialog_content = "Guarding... our home.",
  ui_story_5066_50661801_23_dialog_content = "Forever, you... won't be alone...",
  ui_story_5066_50661801_24_dialog_content = "(So this means... The Aqua Lord didn't completely disappear...)",
  ui_story_5066_50661801_25_dialog_content = "(Instead, it came back... As three different entities!)",
  ui_story_5066_50661801_26_dialog_content = "Uh... Where exactly... Did you three come from...?",
  ui_story_5066_50661801_27_dialog_content = "We come from another dimension!",
  ui_story_5066_50661801_28_dialog_content = "The dimension of illusion!",
  ui_story_5066_50661801_29_dialog_content = "The dimension of imagination!",
  ui_story_5066_50661801_30_dialog_content = "The dimension of music!",
  ui_story_5066_50661801_31_dialog_content = "And there's... Three of you?",
  ui_story_5066_50661801_32_dialog_content = "When you talk, it sounds like a march, a ballad, and a sonata playing all at once.",
  ui_story_5066_50661801_33_dialog_content = "Sorry, I'm having a little trouble telling the three of you apart...",
  ui_story_5066_50661801_34_dialog_content = "I'm playing marches! The most powerful tone!",
  ui_story_5066_50661801_35_dialog_content = "I'm playing ballads, the gentle minor tunes.",
  ui_story_5066_50661801_36_dialog_content = "I'm playing sonata, simple yet profound, in the deeper, wider major key.",
  ui_story_5066_50661801_37_dialog_content = "O mighty Aqua Queen, can you tell us apart now?",
  ui_story_5066_50661801_38_dialog_content = "I can tell you apart perfectly now! You each have such beautiful voices, too!",
  ui_story_5066_50661801_39_dialog_content = "But still, why were you reborn as three different beings...?",
  ui_story_5066_50661801_40_dialog_content = "It's awkward for the noble Aqua Lord to admit it, but it has only one attendant! Having three adds to the majesty!",
  ui_story_5066_50661801_41_dialog_content = "With just one buddy, you might feel lonely at times, but with three, that won't be the case.",
  ui_story_5066_50661801_42_dialog_content = "Having one companion is not enough for a solid family, but three are enough to address the difficulty.",
  ui_story_5066_50661801_43_dialog_content = "Connolly! Starting today, let us be the ones to keep you company!"
}
return config
